  "계정 상태를 확인하지 못했어요. 연결 후 다시 확인해 주세요.":
      "Couldn't check your account. Reconnect and try again.",
  "로그인을 취소했어요.": "Sign-in canceled.",
  "기존 이메일 계정으로 로그인했어요. 받은 인증 메일을 확인해 주세요.":
      "Signed in with your email account. Please check your verification email.",
  "로그인했어요. 이 기기의 기록은 그대로 유지돼요.":
      "You're signed in. Your records on this device are safe.",
  "로그인했어요. 구독 상태는 연결 후 다시 확인해 주세요.":
      "You're signed in. Reconnect to check your subscription.",
  "기존에 이용한 이메일과 비밀번호를 입력해 주세요.":
      "Enter the email and password you used before.",
  "비밀번호를 재설정할 이메일을 먼저 입력해 주세요.":
      "Enter your email address to reset your password.",
  "등록된 이메일이면 비밀번호 재설정 안내를 받을 수 있어요. 스팸함도 확인해 주세요.":
      "If that email is registered, you'll receive password reset instructions. Check your spam folder too.",
  "아직 이메일 인증 전이에요. 메일의 인증 링크를 눌러 주세요.":
      "Your email isn't verified yet. Follow the link in your verification email.",
  "인증 메일을 다시 보냈어요. 받은편지함과 스팸함을 확인해 주세요.":
      "Verification email sent. Check your inbox and spam folder.",
  "로그아웃할까요?": "Sign out?",
  "이 기기의 기록과 정원은 남고 자동 백업은 꺼져요. 다른 로그인 방식은 별도 계정일 수 있으니, 구매할 때 사용한 계정을 기억해 주세요.":
      "Your records and garden stay on this device, and automatic backup turns off. Different sign-in methods may use different accounts, so remember the one you used for purchases.",
  "로그아웃": "Sign out",
  "로그아웃했어요. 이 기기의 기록은 그대로 남아 있어요.":
      "Signed out. Your records are still on this device.",
  "현재 계정에 Google 로그인을 연결할까요?": "Link Google sign-in to this account?",
  "이메일 계정의 구매 내역과 계정 번호를 유지하며, 이후에는 선택한 Google 계정으로도 로그인해요. 다른 마음냥 계정에 이미 연결된 Google 계정은 합칠 수 없어요.":
      "Keep your account ID and purchases, and sign in with Google too. A Google account already linked to another Mindnyang account can't be merged.",
  "연결하기": "Link account",
  "현재 계정에 Google 로그인을 연결했어요.": "Google sign-in is now linked.",
  "연결을 취소했어요.": "Linking canceled.",
  "편한 방법으로 시작해요": "Make yourself at home",
  "함께 가꾸는 나의 계정": "Your garden account",
  "별도의 가입 양식 없이 로그인할 수 있어요. 처음 로그인하면 마음냥 계정이 만들어져요.":
      "No separate sign-up form. Your first sign-in creates a Mindnyang account.",
  "로그인 정보와 서버에서 확인한 구독을 관리해요.":
      "Manage your sign-in details and verified subscription.",
  "구글로 계속하기": "Continue with Google",
  "카카오로 계속하기": "Continue with Kakao",
  "네이버로 계속하기": "Continue with Naver",
  "페이스북으로 계속하기": "Continue with Facebook",
  "이 버전은 계정 연결 준비 중이에요. 기록과 정원은 로그인 없이 이용할 수 있어요.":
      "Account sign-in isn't available in this build yet. You can still use your journal and garden without signing in.",
  "간편 로그인은 현재 안드로이드 앱에서 이용할 수 있어요. 웹 미리보기에서는 로그인 화면을 확인할 수 있어요.":
      "Sign-in is currently available in the Android app. This web preview shows the sign-in screen only.",
  "카카오·네이버·페이스북 로그인은 현재 연결 준비 중이에요.":
      "Kakao, Naver, and Facebook sign-in are not available yet.",
  "기존 구매 내역이 있다면 구매할 때 사용한 로그인 방법을 선택해 주세요. 계정은 자동으로 합쳐지지 않아요.":
      "If you've made a purchase, use the same sign-in method. Accounts aren't merged automatically.",
  "기존 이메일 계정으로 로그인": "Use an existing email account",
  "이메일": "Email",
  "비밀번호": "Password",
  "기존 계정 로그인": "Sign in to existing account",
  "비밀번호 재설정": "Reset password",
  "{0} 로그인": "{0} sign-in",
  "Google 로그인 연결됨": "Google sign-in linked",
  "계정 확인 완료": "Account verified",
  "계정 확인이 필요해요": "Please verify your account",
  "임시 계정으로 이용 중이에요. 로그아웃 후 간편 로그인을 선택해 주세요. 이 기기의 기록은 그대로 유지돼요.":
      "You're using a temporary account. Sign out, then choose a sign-in provider. Records on this device will stay safe.",
  "기존 이메일 계정은 인증 후 구독·구매·공개 정원을 이용할 수 있어요.":
      "Verify your email to use subscriptions, purchases, and public gardens.",
  "이메일 인증 확인": "Check email verification",
  "인증 메일 다시 받기": "Resend verification email",
  "이 계정으로 계속하기": "Continue with this account",
  "계정 상태 다시 확인": "Check account again",
  "현재 계정에 Google 로그인 연결": "Link Google sign-in",
  "기록 백업·계정 삭제 관리": "Backup & account deletion",
  "로그인해도 기록과 정원이 자동으로 다른 기기로 옮겨지지는 않아요. 기기를 바꿀 때는 기록 백업·복원을 이용해 주세요.":
      "Signing in doesn't automatically move your journal and garden to another device. Use backup and restore when switching devices.",
  "개인정보처리방침": "Privacy policy",
  "무료 이용 중": "Free plan",
  "구독 구매와 복원은 Google Play에서 설치한 Android 앱에서 이용할 수 있어요.":
      "Purchase and restore subscriptions in the Android app installed from Google Play.",
  "언제든 해지할 수 있어요 · 구독은 자동 갱신됩니다":
      "Cancel anytime · Subscriptions renew automatically",
  "최신 구독 상태를 확인하지 못했어요. 기존 이용 상태는 유지돼요. 잠시 후 다시 확인해 주세요.":
      "Couldn't refresh your subscription. Your existing access is unchanged. Please check again later.",
  "이용 상태를 확인하지 못했어요. 다시 확인해 주세요.":
      "Couldn't check your access. Please try again.",
  "연간 구독으로 바꿀까요?": "Switch to a yearly plan?",
  "연간 {0}를 지금 결제하는 방식이에요. 남은 월간 이용분은 Google Play가 새 이용 기간에 반영해요. 최종 금액과 다음 결제일을 Play 결제 화면에서 확인한 뒤 승인해 주세요. 기존 월간 구독을 대체하며, 취소하면 현재 구독이 유지돼요.":
      "You'll pay {0} for the yearly plan now. Google Play will account for your remaining monthly access. Review the final price and next billing date in Google Play before confirming. This replaces your monthly plan; canceling this change keeps your current plan.",
  "돌아가기": "Go back",
  "Play에서 확인": "Review in Google Play",
  "구매가 완료되지 않았어요. 잠시 후 다시 확인해 주세요.":
      "Purchase not completed. Please check again shortly.",
  "마음냥 구독 이용 중": "Mindnyang Premium active",
  "마음냥 구독 멤버십이 시작되었어요 🌷": "Welcome to Mindnyang Premium 🌷",
  "구독 관리 화면을 열지 못했어요. Play 스토어 → 프로필 → 결제 및 정기 결제 → 정기 결제에서 해지할 수 있어요.":
      "Couldn't open subscription management. In Google Play, go to Profile → Payments & subscriptions → Subscriptions to cancel.",
  "마음냥 구독": "Mindnyang Premium",
  "간편 로그인 · 구매 계정 관리": "Sign-in & purchase account",
  "이미 마음냥 구독 멤버십을 이용 중이에요 🌿": "You're already a Premium member 🌿",
  "멤버십 해지하기": "Cancel subscription",
  "Google Play 화면에서 해지를 완료해 주세요. 해지 후에도 이미 결제한 기간까지 이용할 수 있어요.":
      "Complete cancellation in Google Play. You'll keep access until the end of your paid period.",
  "연간으로 변경 · {0}": "Switch to yearly · {0}",
  "Play 결제 화면에서 남은 이용 기간 반영과 금액을 확인할 수 있어요.":
      "Review the price and credit for your remaining time in Google Play.",
  "구독 상태 확인 중…": "Checking subscription…",
  "구독 상태 다시 확인": "Refresh subscription",
  "Android 앱에서 이용": "Available in the Android app",
  "결제 연결 준비 중": "Purchases aren't available yet",
  "구독 상품 확인 필요": "Subscription details unavailable",
  "구매 복원": "Restore purchases",
  "구독 상품 다시 확인": "Reload plans",
  "현재 이용 중 ✓ (연간)": "Current plan ✓ (Yearly)",
  "현재 이용 중 ✓ (월간)": "Current plan ✓ (Monthly)",
  "현재 이용 중 ✓": "Current plan ✓",
  "정원을 더 깊이\n돌아볼 수 있어요": "More ways to grow,\nmore moments to keep",
  "기록과 기본 정원은 무료로 시작해요.\n구독으로 장식과 이야기, 돌아보는 경험을 넓혀보세요.\n오프라인 클래스는 현재 구독 혜택에 포함되지 않아요.":
      "Your journal and basic garden are free.\nPremium adds decorations, stories, and more ways to reflect.\nIn-person classes are not included.",
  "월간": "Monthly",
  "언제든 부담 없이": "A little time for you",
  "연간": "Yearly",
  "매년 결제": "Billed yearly",
  "내 시간이 쌓이는 정원": "A garden full of your moments",
  "구독 장식과 공개된 정원 이야기를 이어가요. 이미 받은 장식은 구독이 끝나도 남아요.":
      "Enjoy Premium decorations and available garden stories. Decorations you've already received stay yours after your subscription ends.",
  "나를 돌아보는 월간 기록집": "Your monthly scrapbook",
  "내가 고른 문장·나무의 기억·돌봄 경험을 한 달씩 모아요. 첫 기본 기록집은 무료이고, 기존 기록집은 계속 볼 수 있어요.":
      "Gather favorite words, tree memories, and moments of care each month. Your first basic scrapbook is free, and existing scrapbooks stay available.",
  "함께 만드는 기억": "Memories made together",
  "이웃을 초대해 기념 나무를 함께 가꿔요. 초대받은 친구는 무료로 참여할 수 있어요.":
      "Invite a neighbor to grow a tree for a special occasion. Invited friends can join for free.",
  "광고 없이 이용": "An ad-free space",
  "구독 기간과 구독 무료체험 기간에는 홈 배너 광고가 표시되지 않아요":
      "No home banner ads during your subscription or free trial.",
  "그 밖의 구독 혜택": "More Premium benefits",
  "상세 주간·월간 통계와 지난달·분기 비교, 요일·시간대 기록 패턴, ":
      "Explore detailed weekly and monthly insights, comparisons over time, and journaling patterns by day and time. ",
  "나에게 도움이 됐던 돌봄의 긴 기간 비교, 감정을 돌아보는 질문, ":
      "Look back at the care that helped you and reflect with gentle prompts. ",
  "오늘의 카드와 내 마음, 돌봄 온기 포인트, 주제별 실천 여정을 이용할 수 있어요. ":
      "Enjoy daily cards, care points, and themed self-care journeys. ",
  "정원의 다음 이야기는 구독과 기록 3일·5일 조건으로 열려요. ":
      "Later garden stories unlock with Premium and 3 or 5 days of journaling. ",
  "오프라인 클래스 참가비는 구독에 포함되지 않아요.": "In-person class fees are not included.",
  "마음냥 구독 시작하기": "Get Mindnyang Premium",
  "흰고양이": "White cat",
  "고등어태비": "Silver tabby",
  "검정고양이": "Black cat",
  "턱시도 고양이": "Tuxedo",
  "삼색 고양이": "Calico",
  "참치 간식": "Tuna treat",
  "닭고기 간식": "Chicken treat",
  "사료 꾸러미": "Kibble",
  "꽃": "Flower",
  "응원": "Encouragement",
  "받은 꽃": "Gifted flower",
  "꽃을 선물했어요": "sent you a flower",
  "응원을 보냈어요": "sent you encouragement",
  "요청을 완료하지 못했어요. 다시 시도해 주세요.":
      "Couldn't finish that request. Please try again.",
  "산책 새로 불러오기": "Reload walk",
  "가로·세로 전체 화면": "Full screen in either orientation",
  "산책은 Android·iPhone 앱에서 이용할 수 있어요.":
      "Cat walks are available in the Android and iPhone apps.",
  "산책을 불러오지 못했어요 · 다시 시도": "Couldn't load your walk · Try again",
  "전체 화면 닫기": "Exit full screen",
  "확인 완료": "Read",
  "고양이 정보 없음": "Cat appearance unavailable",
  "새 선물을 모두 확인했어요.": "You're all caught up!",
  "전체 선물": "All gifts",
  "내 정원에 심기": "Plant in my garden",
  "과일·간식은 자동 보관돼요. 모두 받기는 불러온 꽃 선물을 보관해요.":
      "Fruit and treats are saved automatically. Collect all saves the flower gifts shown here.",
  "{0}개를 보관했어요. 잠시 뒤 남은 선물을 다시 받아 주세요.":
      "Saved {0} gifts. Please try collecting the rest again shortly.",
  "새 소식을 가져오지 못했어요. 이전 목록을 표시하고 있어요. 아래로 당겨 다시 시도해 주세요.":
      "Couldn't refresh your updates. Your previous list is still here. Pull down to try again.",
  "기록은 현재 이 기기에 저장됩니다.": "Your entries are currently saved on this device.",
  "휴대전화 설정에서 PIN·패턴·비밀번호 잠금을 먼저 설정해 주세요.":
      "Set up a PIN, pattern, or password in your phone settings first.",
  "로그인 정보를 확인해 주세요. 이메일 인증 또는 비밀번호 재설정이 필요할 수 있어요.":
      "Please check your sign-in details. You may need to verify your email or reset your password.",
  "완료하지 못했어요. 암호·파일·저장 공간과 연결을 확인해 주세요. 기존 기록은 지우지 않았어요.":
      "Couldn't finish. Check your password, file, storage space, and connection. Your existing entries haven't been deleted.",
  "백업 암호 정하기": "Create a backup password",
  "백업 암호 입력": "Enter your backup password",
  "앱 로그인 암호와 별개예요. 암호를 잃으면 새 기기에서 백업을 복원할 수 없어요. 안전한 곳에 보관해 주세요.":
      "This is separate from your sign-in password. Without it, you won't be able to restore this backup on a new device. Keep it somewhere safe.",
  "백업 암호": "Backup password",
  "암호 다시 입력 (12자 이상)": "Confirm password (at least 12 characters)",
  "암호화 백업 저장": "Save encrypted backup",
  "암호화 백업 파일을 저장했어요. 파일과 암호를 안전한 곳에 보관해 주세요.":
      "Encrypted backup saved. Keep the file and its password somewhere safe.",
  "복원 미리보기": "Preview restore",
  "기존 항목과 같은 ID는 현재 기록을 유지하고, 없는 항목만 추가해요.\n":
      "Existing entries with the same ID will stay as they are. Only missing entries will be added.\n",
  "복원을 마치면 복원한 정원을 바로 열 수 있어요.":
      "You can open your restored garden as soon as the restore finishes.",
  "복원": "Restore",
  "복원 완료": "Restore complete",
  "파일이 너무 커요.": "This file is too large.",
  "이전 버전에서 추가로 가져올 기록이 없어요.":
      "There are no additional entries to recover from the previous version.",
  "이전 버전의 기록 확인": "Review entries from an earlier version",
  "이전 버전에서 남아 있는 기록이에요. 이미 삭제했던 기록이 포함될 수 있어요. ":
      "These entries were found in an earlier version. They may include entries you previously deleted. ",
  "확인하면 현재 없는 기록만 추가하고 같은 ID는 현재 기록을 유지해요.":
      "Only missing entries will be added. Existing entries with the same ID will stay as they are.",
  "이전 기록 복원 완료": "Earlier entries restored",
  "서버에 저장된 백업이 없어요.": "You don't have any cloud backups yet.",
  "복원할 백업 선택": "Choose a backup to restore",
  "기록 보관과 백업": "Storage & backup",
  "소중한 기록을 안전하게": "Keep your memories safe",
  "편지는 기기에 자동 저장해요. 앱 삭제·분실에 대비하려면 별도 백업이 필요해요.":
      "Letters are saved automatically on this device. Make a separate backup to protect them if you lose your device or uninstall the app.",
  "암호화 백업 파일 저장": "Save encrypted backup file",
  "백업 파일에서 복원": "Restore from a backup file",
  "이전 버전의 누락 기록 확인": "Check for missing entries from an earlier version",
  "앱 개선을 위한 사용 통계 공유": "Share usage data to help improve the app",
  "선택 사항이에요. 일기 본문·선택한 감정은 보내지 않아요. Firebase가 앱 인스턴스·기기 정보를 처리할 수 있어요.":
      "Optional. Your journal text and selected emotions are not sent. Firebase may process app instance and device information.",
  "앱 잠금": "App lock",
  "휴대전화 PIN·패턴·비밀번호로 열어요. 잠금을 켜면 화면 캡처와 최근 앱 미리보기도 차단해요.":
      "Unlock with your phone's PIN, pattern, or password. Turning this on also blocks screenshots and recent-app previews.",
  "앱 잠금을 켰어요.": "App lock is on.",
  "앱 잠금을 껐어요.": "App lock is off.",
  "잠금 변경을 취소했어요.": "App lock change canceled.",
  "보류한 복원이 없어요.": "There is no paused restore to resume.",
  "보류한 복원 완료": "Paused restore completed",
  "보류한 복원 다시 시도": "Resume restore",
  "보류한 복원을 그만할까요?": "Stop this restore?",
  "이미 추가된 기록은 유지해요. 아직 추가되지 않은 내용은 자동으로 복원하지 않으며 복원 원본은 기기에 암호화 보관해요. 이후 원본 백업 파일로 다시 복원할 수 있어요.":
      "Entries already added will stay. Remaining entries won't be restored automatically, and the restore source will remain encrypted on this device. You can restore again later using the original backup file.",
  "복원 그만하기": "Stop restore",
  "보류한 복원을 마무리했어요. 현재 기록을 유지하며 새 백업·복원을 이용할 수 있어요.":
      "The paused restore has been closed. Your current entries are safe, and you can back up or restore again.",
  "보류한 복원 그만하기": "Stop paused restore",
  "카카오 · 네이버 · 구글 · 페이스북": "Kakao · Naver · Google · Facebook",
  "서버 백업은 연결 준비 후 이용할 수 있어요. 현재는 위의 파일 백업을 이용해 주세요.":
      "Cloud backup isn't available yet. Please use file backup above for now.",
  "서버 백업을 이용하려면 위에서 로그인해 주세요.": "Sign in above to use cloud backup.",
  "이 기기의 정원 전체를 이 계정에 백업합니다. 처음 백업하거나 서버에서 복원한 계정에 연결되며 다른 계정으로는 백업·복원할 수 없어요. 로그아웃해도 기기 기록은 남아요.":
      "Your entire garden on this device will be backed up to this account. It is linked to the account you first use to back up or restore from the cloud. You can't back up or restore it with a different account. Signing out doesn't remove entries from this device.",
  "자동 백업은 구독 중 앱을 사용하는 동안 1분마다 변경을 확인해요. 새 기록이 있으면 마지막 백업 이후 최소 2분 간격으로 저장해요. 앱이 닫혀 있거나 연결이 끊기면 다음에 열 때 다시 시도해요. 최근 10개 버전을 보관하며 구독 종료 후에도 기존 백업은 복원할 수 있어요.":
      "While your subscription is active and the app is open, auto-backup checks for changes every minute. New entries are backed up at least two minutes after the last backup. If the app closes or loses connection, it tries again when you reopen it. Your 10 most recent versions are kept. You can still restore existing backups after your subscription ends.",
  "이 계정에 자동 백업할까요?": "Turn on auto-backup for this account?",
  "백업 암호를 기기의 보안 저장소에 보관해 자동 백업에 사용해요. 새 기기에서 복원할 암호는 별도로 보관해 주세요. 암호를 변경하면 이전 백업에는 이전 암호가 필요해요.":
      "Your backup password will be kept in secure storage on this device for automatic backups. Keep a separate copy so you can restore on a new device. If you change the password, older backups will still need their original password.",
  "켜기": "Turn on",
  "자동 백업 켜기": "Turn on auto-backup",
  "지금 서버에 백업": "Back up to the cloud now",
  "자동 백업 끄기": "Turn off auto-backup",
  "서버 백업에서 복원": "Restore from cloud backup",
  "서버 계정과 백업을 삭제할까요?": "Delete your cloud account and backups?",
  "이 작업은 되돌릴 수 없어요. 함께 가꾸는 나무와 그 안의 공유 메모는 두 사람 모두에게서 삭제돼요. 기기 기록과 Play 구독은 별도로 남아요. 구독 해지는 Play에서 해주세요. 최근 5분 이내 로그인해야 삭제할 수 있어요.":
      "This can't be undone. Shared trees and their shared notes will be deleted for both people. Entries on this device and your Google Play subscription will remain. Cancel your subscription through Google Play separately. To delete your account, you must have signed in within the last five minutes.",
  "삭제": "Delete",
  "서버 계정과 백업을 삭제했어요. 이 기기 기록은 남아 있어요.":
      "Your cloud account and backups have been deleted. Entries on this device are still here.",
  "서버 계정과 백업 삭제": "Delete cloud account & backups",
  "편지를 저장하지 못했어요. 다시 보내 주세요":
      "Couldn't save your letter. Please try sending it again.",
  "오늘은 조금 지쳤어… 한 줄이면 충분해요.":
      "A little tired today… A line or two is enough.",
  "글 대신 감정 하나만 골라도 괜찮아요.":
      "You can simply choose a feeling instead of writing.",
  "기록은 나중에, 먼저 시작할래요": "Skip writing for now",
  "보내기": "Send",
  "당신의 속도로 가꾸는 정원": "A garden that grows at your pace",
  "기억의 씨앗에 소중한 날짜와 마음을 담아요.\n기록하지 않는 날에는 정원에서 쉬어도 괜찮아요.":
      "Plant a memory seed with a meaningful date and a few words.\nOn days you don't feel like writing, you can simply rest in your garden.",
  "이 기기에서 계속하기": "Continue on this device",
  "계정 로그인 없이 이 기기에만 저장돼요.\n앱을 삭제하면 기록도 함께 사라질 수 있어요.":
      "Your entries stay on this device without an account.\nUninstalling the app may delete them.",
