  "살짝 알려드릴게요": "A little tip",
  "감정 고양이의 별표는 즐겨찾기예요. 마음편지는 상대에게 전송되지 않는 개인 기록이에요. 일부 기능은 구독·로그인 또는 쌓인 기록이 필요해요.":
      "Tap a mood cat's star to save it as a favorite. Letters from the heart are private entries, not messages sent to someone else. Some features need a subscription, sign-in, or previous entries.",
