  "새로고침": "Refresh",
  "기억하고 싶은 날,\n씨앗 하나를 심어요.": "Plant a seed\nfor a day you want to remember.",
  "사랑도, 용서도, 평화도.\n내가 고른 씨앗에 날짜와 이야기를 담아 천천히 키워요.":
      "Love, forgiveness, or peace.\nChoose a seed, add a date and a story, and let it grow at your pace.",
  "기억의 씨앗 심기 · 나무 키우기": "Plant a memory seed · Grow a tree",
  "기억의 씨앗 심기": "Plant a memory seed",
  "아직 심은 씨앗이 없어요.\n처음부터 큰 나무가 생기지 않아요.":
      "No seeds planted yet.\nYour trees begin as seeds and grow with you.",
  "{0} · 추억 {1}개": "{0} · Memories: {1}",
  "함께 돌본 {0}일": "Days cared for together: {0}",
  "추억 보기 · 돌보기  →": "Memories & care →",
  "쉬는 날에도 시들지 않아요. 기록한 날짜와 내용은 나만 볼 수 있어요. 설정의 데이터 백업에 기억의 나무도 함께 담겨요.":
      "Your trees won't wither when you take a break. Dates and memories are private. Memory trees are included in your data backup in Settings.",
  "이전 정원 식물에 남긴 추억 보기": "Memories saved with earlier garden plants",
