  "씨앗을 저장하지 못했어요. 다시 시도해주세요.": "Couldn't save your seed. Please try again.",
  "기억의 씨앗 고르기": "Choose a memory seed",
  "어떤 마음을 심을까요?": "What would you like to plant?",
  "{0}의 씨앗": "Seed of {0}",
  "자라날 나무의 빛깔": "Preview your tree's colors",
  "나무 이름": "Tree name",
  "예: 엄마와의 봄날": "For example: Spring days with Mom",
  "기념할 날짜": "Date to remember",
  "기억하고 싶은 내용": "A memory to keep",
  "이 씨앗에 담고 싶은 사람, 순간, 약속을 적어주세요.":
      "Write about a person, a moment, or a promise you'd like this seed to hold.",
  "기념일과 실제 심은 날은 따로 기록해요. 과거 날짜를 적어도 오늘은 씨앗부터 시작해요.":
      "The anniversary and planting date are saved separately. Even if you choose a past date, your tree starts as a seed today.",
  "씨앗을 심고 있어요…": "Planting your seed…",
  "이 기억으로 씨앗 심기": "Plant this memory",
  "기억하고 싶은 날짜": "Choose a date to remember",
  "저장하지 못했어요. 새로고침 후 다시 시도해주세요.": "Couldn't save. Refresh and try again.",
  "삭제된 나무예요. 목록으로 돌아가주세요.":
      "This tree has been deleted. Please return to the list.",
  "나무 이름과 빛깔": "Tree name & colors",
  "저장": "Save",
  "이름·빛깔 수정": "Edit name & colors",
  "{0}의 씨앗에서 자라는 {1} 기억": "A {1} memory tree, grown from a seed of {0}",
  "심은 날 {0} · 돌본 {1}일": "Planted {0} · Days cared for: {1}",
  "나무는 다 자랐지만 추억은 계속 쌓을 수 있어요.":
      "Your tree is fully grown, but you can keep adding memories.",
  "{0}일 더 돌보면 다음 모습으로 자라요.":
      "Care for your tree on {0} more days to see its next stage.",
  "오늘의 물과 마음 주기": "Water your tree today",
  "오늘은 돌봄을 마쳤어요": "Today's care is complete",
  "한국 날짜 기준 하루 한 번 자라요. 씨앗 → 새싹(3일) → 어린 나무(7일) → 빛나는 나무(14일) → 보석나무(30일). 쉬어도 성장은 줄어들지 않아요.":
      "Growth happens once per day, based on Korean time. Seed → Sprout (3 days) → Young tree (7 days) → Glowing tree (14 days) → Gem tree (30 days). Taking a break won't undo its growth.",
  "이 나무에 담긴 추억": "Memories saved with this tree",
  "추억 더하기": "Add a memory",
  "날짜·내용 수정": "Edit date & memory",
  "이 추억을 삭제할까요?": "Delete this memory?",
  "이 날짜에 남긴 내용만 삭제하며 나무의 성장은 그대로 유지해요.":
      "Only the words saved for this date will be deleted. Your tree's growth will stay.",
  "추억 삭제": "Delete memory",
  "기억의 나무를 삭제할까요?": "Delete this memory tree?",
  "이 나무의 추억 {0}개와 성장 기록을 모두 삭제해요. 앱 안에서는 되돌릴 수 없어요.":
      "This will delete all {0} memories and the growth history for this tree. It can't be undone in the app.",
  "이 나무와 추억 전체 삭제": "Delete this tree and all its memories",
  "추억 수정": "Edit memory",
  "기억하고 싶은 내용을 적어주세요.": "Write what you'd like to remember.",
  "이 추억 저장": "Save this memory",
  "개인정보 · 이용안내": "Privacy & app information",
  "수집하는 정보": "Information we collect",
  "마음냥 정원은 다음과 같은 정보를 앱 안에서 만들고 저장합니다.\n\n· 오늘의 감정 카드 선택 기록, 마음 온도 기록\n· 고양이에게 쓴 편지(일기) 내용\n· 먹이주기 · 물주기 · 목욕 · 청소 등 돌보기 기록\n· 명상 · 내면소통 완료 기록, 연속 방문일, 성장 레벨\n\n· 선택한 편지 마무리 감정·문장, 돌봄 계획·실천 여부·도움 여부, 직접 간직한 응원\n· 정원 기록집에 선택한 문장·나무·실천 기록, 정원 모습의 저장 시각과 나중에 덧붙인 글\n\n기록과 초안은 기기에 저장하며 암호화를 적용합니다. 파일 백업을 선택하면 사용자가 지정한 위치에 암호화 파일을 저장합니다.\n\n{0}\n\n간편 로그인에는 Firebase Authentication을 사용합니다. 구글 로그인을 선택하면 Firebase가 제공받는 계정 식별자·이름·이메일·프로필 정보가 인증에 사용될 수 있습니다. 카카오·네이버·페이스북 로그인은 서버에서 제공사 계정 ID를 확인하고 해시 처리한 연결 식별자와 Firebase 계정 식별자를 보관합니다. 이 세 방식은 이메일·친구 목록·게시물·일기 내용을 요청하지 않습니다. 로그인 세션은 짧은 유효기간과 일회용 확인 절차로 보호합니다.\n\n이웃·예약 소식 알림을 켜면 Firebase Cloud Messaging의 기기 등록 토큰·계정 식별자·알림 선택을 서버에 저장합니다. 알림에는 편지나 감정 내용을 넣지 않습니다. 마이에서 끌 수 있고 로그아웃 시 기기 연결을 해제합니다. 30일 이상 갱신되지 않은 기기에는 보내지 않습니다.\n\n사용 통계 공유는 기본으로 꺼져 있으며 기록 보관과 백업에서 선택할 수 있습니다. 켜면 기능 이용 이벤트와 제한된 항목을 Firebase Analytics에 보냅니다. 일기 본문·선택한 감정은 보내지 않습니다. Firebase SDK는 앱 인스턴스 식별자·기기 및 앱 정보를 처리할 수 있으므로 완전히 익명인 통계라고 보장하지 않습니다.":
      "Mindnyang Garden creates and stores the following information in the app:\n\n• Daily mood card selections and care warmth records\n• Letters (journal entries) written to cats\n• Care activities such as feeding, watering, bathing, and cleaning\n• Meditation and reflection completion, consecutive visits, and growth levels\n\n• Feelings and phrases chosen when finishing a letter, self-care plans, completion and helpfulness responses, and encouragement you choose to save\n• Sentences, trees, and activities selected for garden books, the time a garden scene was saved, and words added later\n\nEntries and drafts are stored on your device with encryption. If you choose file backup, an encrypted file is saved to a location you select.\n\n{0}\n\nSocial sign-in uses Firebase Authentication. If you choose Google sign-in, account identifiers, your name, email address, and profile information received by Firebase may be used for authentication. For Kakao, Naver, and Facebook sign-in, the server verifies the provider's account ID and stores a hashed linking identifier and Firebase account identifier. These three methods do not request your email, friend list, posts, or journal entries. Sign-in sessions are protected by short expiration periods and one-time verification.\n\nIf you enable neighbor or booking notifications, the server stores a Firebase Cloud Messaging device registration token, account identifier, and notification preferences. Notifications do not contain letters or mood details. You can turn them off in My account; signing out disconnects the device. Notifications are not sent to devices that have not refreshed their registration for more than 30 days.\n\nUsage sharing is off by default and can be enabled in Storage & backup. When enabled, feature-use events and a limited set of attributes are sent to Firebase Analytics. Journal text and selected emotions are not sent. The Firebase SDK may process app instance identifiers and device and app information, so these statistics are not guaranteed to be completely anonymous.",
  "서버 백업을 직접 켜면 정원 기록·초안·답장이 백업 암호로 암호화되어 서버로 전송됩니다. 로그인 이메일과 계정 식별자, 구매 토큰과 구독 상태도 계정·결제 기능에 사용됩니다.":
      "If you turn on cloud backup, garden entries, drafts, and replies are encrypted with your backup password before being sent to the server. Your sign-in email, account identifier, purchase tokens, and subscription status are also used for account and payment features.",
  "서버 백업은 연결 준비 후 이용할 수 있습니다.":
      "Cloud backup will be available once the connection is configured.",
  "정보 사용 목적과 보관": "How information is used and kept",
  "마음 기록은 이용자 본인의 마음챙김 기록을 보여주고, 고양이 성장 · 마음 리포트 · 직접 선택한 이웃 교류 등 앱의 핵심 기능을 제공하기 위한 목적으로만 사용됩니다.\n\n편지를 삭제하면 해당 본문은 기록 목록에서 사라집니다. 나무의 성장을 유지하고 같은 날 중복 성장을 막기 위한 기록 날짜는 정원 성장 정보에 남습니다. 이 날짜와 편지 본문은 공개 정원에 표시하지 않습니다.\n\n편지의 문장을 내 식물의 기억에 연결하면 원본 편지의 식별자와 날짜, 직접 고른 문장을 기기에 저장합니다. 이 기억은 개인 기록이며 공개 정원이나 공동 나무로 전송하지 않습니다. 편지를 삭제할 때 연결된 마무리 기록과 식물 기억·정원 기록집의 해당 문장도 지웁니다. 돌봄 실천이나 식물 기억을 삭제하면 기록집에 선택해 둔 해당 항목도 지웁니다. 이미 외부로 공유한 파일과 이전 백업에는 사본이 남을 수 있습니다. 기록집의 정원 그림은 표시된 저장 시각에 보관한 배치를 다시 그린 것이며, 과거 날짜에 촬영한 사진은 아닙니다.\n\n앱 삭제는 기기 기록에 영향을 줍니다. 별도로 내보낸 파일이나 서버 백업까지 삭제되지는 않습니다. 기록 하나를 지워도 이전 백업에는 남을 수 있습니다.\n\n{0}\n\n백업 암호는 서버로 보내지 않으며, 자동 백업을 켠 경우 기기 보안 저장소에 보관합니다. 암호를 잊으면 새 기기에서 복원할 수 없습니다. 한 기기에는 하나의 정원이 저장되며 로그아웃으로 기기 기록이 지워지지 않습니다.":
      "Mood entries are used to show your personal mindfulness records and provide core features such as cat growth, mood reports, and neighbor interactions you choose.\n\nDeleting a letter removes its text from your entry list. Its date remains in garden growth data to preserve tree growth and prevent duplicate growth on the same day. Neither this date nor the letter text appears in your public garden.\n\nIf you link a sentence from a letter to a plant memory, the original letter identifier, date, and sentence you selected are stored on your device. This is a private entry and is not sent to a public garden or shared tree. Deleting a letter also removes its linked closing reflections and selected sentences in plant memories and garden books. Deleting a self-care activity or plant memory removes that selected item from garden books too. Copies may remain in files you have already shared and in earlier backups. Garden illustrations in books redraw the layout saved at the displayed time; they are not photographs taken on a past date.\n\nUninstalling the app affects entries on your device. It does not delete exported files or cloud backups. Deleting an individual entry may leave copies in earlier backups.\n\n{0}\n\nYour backup password is not sent to the server. If you enable auto-backup, it is kept in secure storage on your device. Without the password, you cannot restore on a new device. One garden is stored per device, and signing out does not delete its entries.",
  "서버는 최근 10개 백업을 보관하며 구독 종료 후에도 기존 백업 복원을 허용합니다. 서버 계정과 백업 삭제는 기록 보관과 백업에서 요청할 수 있습니다. 중복 구매 연결을 막기 위한 구매 토큰의 해시 표식은 원문 토큰·계정 식별자 없이 남습니다. 계정 해시 기반 삭제 상태와 소셜 로그인 연결 식별자·연결 UID·세대 정보도 남으며 현재 자동 만료기간은 없습니다. 정식 운영 보유기간과 최소 보관 범위는 확정 전입니다.":
      "The server keeps the 10 most recent backups and allows existing backups to be restored after a subscription ends. You can request deletion of your cloud account and backups in Storage & backup. A hash marker of each purchase token remains to prevent the same purchase being linked more than once, without the original token or account identifier. Account-hash-based deletion status, social sign-in linking identifiers, linked UIDs, and generation data also remain, with no automatic expiry currently set. Retention periods and the minimum data to retain for full operation have not yet been finalized.",
  "내보낸 백업 파일은 저장한 위치에서 직접 관리·삭제해 주세요.":
      "Manage and delete exported backup files directly in the location where you saved them.",
  "냥이 마을 · 이웃과 나누는 정보": "Cat village · Information shared with neighbors",
  "온라인 이웃 기능을 이용하면 계정 식별자, 정원 닉네임, 초대 코드, 공개 범위, 이웃 신청·수락 관계, 차단 설정을 서버에 저장합니다. 초대 코드를 가진 사람은 닉네임을 확인하고 이웃 신청을 보낼 수 있으며, 신청을 수락해야 이웃으로 연결됩니다.\n\n정원은 나만 보기 · 이웃에게 공개 · 모두에게 공개 중 선택할 수 있습니다. 정원 둘러보기 목록에는 모두에게 공개하고 목록 노출에도 동의한 정원만 나타납니다. 공개하는 정원 모습에는 씨앗 수, 장식, 나무 성장 단계와 배치 등이 포함되며, 편지 본문·감정 통계·개인 기록 날짜는 포함하지 않습니다.\n\n응원과 선물을 보내면 선택한 문구·이모티콘·꽃 종류, 보낸 계정과 닉네임, 보낸 날짜, 받기·심기·전달 상태를 서버에서 처리합니다. 상대는 받은 마음에서 보낸 사람과 날짜를 볼 수 있습니다. 정원의 이모티콘 효과는 24시간 동안 표시되지만 받은 마음 기록은 그 이후에도 남을 수 있습니다.\n\n공동 기념 나무는 수락한 이웃을 직접 초대하고 상대가 참여를 수락해야 함께 돌볼 수 있습니다. 나무 이름·기념일·물주기 기록과 공동 메모는 서버에 저장하고 참여자끼리 봅니다. 개인 편지·감정 통계는 공유하지 않습니다. 공동 메모는 작성자가 삭제할 수 있습니다. 이웃 연결이 끝나거나 차단된 뒤에도 ‘내가 남긴 공동 메모 관리’에서 본인의 메모를 삭제할 수 있습니다. 이웃을 다시 연결해도 이전 공동 나무의 참여는 자동으로 재개되지 않으며 새 초대와 수락이 필요합니다. 새 활동 표시를 위해 참여자의 마지막 확인 상태를 저장합니다. 나가기와 계정 삭제의 차이는 나무 화면과 계정 삭제 화면에서 확인할 수 있습니다.\n\n공개 범위와 목록 노출, 선물 받기 설정은 냥이 마을에서 바꿀 수 있습니다. 차단하면 서로의 정원 방문과 새로운 응원·선물 교류를 제한합니다. 신고하면 신고한 계정, 대상 계정과 선택한 신고 사유를 서버에 저장하며, 편지 본문은 신고 정보에 포함하지 않습니다.":
      "Online neighbor features store your account identifier, garden nickname, invite code, visibility, request and acceptance relationships, and blocking settings on the server. Someone with your invite code can see your nickname and send a request. You become neighbors only after a request is accepted.\n\nChoose whether your garden is private, visible to neighbors, or public. Garden discovery shows only public gardens whose owners have also opted into discovery. Shared garden scenes include seed counts, decorations, tree growth stages, and layouts, but not letter text, mood statistics, or private entry dates.\n\nWhen you send encouragement or a gift, the server processes your selected message, emoji, or flower type, your account and nickname, the date sent, and collection, planting, or forwarding status. Recipients can see the sender and date in their inbox. Emoji effects appear in the garden for 24 hours, but inbox records may remain afterward.\n\nTo care for a shared memory tree together, invite an accepted neighbor and wait for them to accept. The tree name, anniversary, watering history, and shared notes are stored on the server and visible to participants. Private letters and mood statistics are not shared. Authors can delete their own shared notes. Even after a neighbor connection ends or a block is applied, you can delete your notes through Manage my shared notes. Reconnecting as neighbors does not automatically restore participation in earlier shared trees; a new invitation and acceptance are required. Each participant's last-viewed status is saved to show new activity. The tree and account deletion screens explain the difference between leaving and deleting an account.\n\nChange visibility, discovery, and gift preferences in Cat village. Blocking restricts mutual garden visits and new encouragement or gifts. Reports store the reporting account, reported account, and selected reason on the server. Letter text is not included in reports.",
  "정원 소식 · 클래스 신청": "Garden updates · Class bookings",
  "클래스나 모임에 신청하면 계정 식별자·선택한 일정·신청 및 취소 상태·신청 메모를 서버에 저장합니다. 운영자는 신청 관리에 필요한 내용을 확인합니다. 편지와 감정 기록은 신청에 포함되지 않습니다.\n\n일정·장소·참가비·신청 마감은 각 공지에 표시합니다. 온라인 참여 주소가 있는 경우 신청한 참여자에게 안내합니다. 앱 구독만으로 모든 클래스의 참가비가 면제되는 것은 아닙니다. 외부 센터로 따로 정보를 전달하거나 외부에서 결제해야 하는 경우 해당 안내를 확인한 후 선택해 주세요.":
      "When you sign up for a class or gathering, the server stores your account identifier, selected session, booking and cancellation status, and booking note. The team can view information needed to manage bookings. Letters and mood entries are not included.\n\nEach announcement states its schedule, venue, fee, and sign-up deadline. Online meeting links, where available, are provided to registered participants. An app subscription does not waive every class fee. Review the details before choosing to send information to an external center or make an external payment.",
  "제3자 제공": "Sharing with third parties",
  "일기 내용을 광고 목적으로 전송하는 기능은 없습니다. 사용자가 공유·백업 파일 저장을 선택하면 해당 대상에 기록이 전달될 수 있습니다.\n\n선택적 통계에는 Firebase Analytics를 사용합니다. 계정 인증에는 Google Firebase와 직접 선택한 로그인 제공사(구글·카카오·네이버·페이스북)를 이용하며, 스토어 결제에는 Google Play를 사용합니다. {0} 새 자동 답장은 만들지 않으며 예전에 저장된 답장만 열람할 수 있습니다. 외부 생성형 AI에 일기를 보내지 않습니다. 정원 기록집을 공유할 때에는 미리보기에서 선택한 내용만 내보냅니다.":
      "The app does not send journal text for advertising. If you choose to share or save a backup file, entries may be sent to the destination you select.\n\nOptional usage statistics use Firebase Analytics. Authentication uses Google Firebase and the sign-in provider you choose: Google, Kakao, Naver, or Facebook. Store payments use Google Play. {0} No new automatic replies are generated; only previously saved replies can be read. Journal entries are not sent to an external generative AI service. Sharing a garden book exports only the content you selected in the preview.",
  "암호화 백업·서버 결제 확인·냥이 마을·공동 나무·클래스 신청 정보 처리에는 Google Firebase를 사용합니다.":
      "Google Firebase processes encrypted backups, server-side payment verification, Cat village, shared trees, and class bookings.",
  "무료 이용과 광고": "Free access & advertising",
  "광고가 연결된 Android 버전에서는 무료 이용자에게 홈 하단의 Google AdMob 배너 광고가 표시될 수 있습니다. 구독과 구독 무료체험 기간에는 광고를 표시하지 않습니다. 편지 작성·정원 산책·명상 화면에는 광고를 넣지 않습니다.\n\n앱은 비맞춤 광고를 요청하며 편지 본문, 선택한 감정, 마음 점수, 나무의 추억, 친구 코드나 로그인 계정을 광고 타기팅 정보로 전달하지 않습니다. 비맞춤 광고도 광고 제공·측정·부정 이용 방지를 위해 Google 광고 SDK가 IP 주소, 광고 상호작용, 진단 정보와 기기 식별자 등을 처리할 수 있습니다. 데이터 수집이 전혀 없는 방식이라는 뜻은 아닙니다.\n\n필요한 지역에서는 광고 개인정보 선택 화면을 제공합니다. 광고가 연결된 버전의 마이 → 광고 개인정보 선택에서 해당 선택을 확인하거나 변경할 수 있습니다. 사용 통계 공유 설정은 광고 개인정보 선택과 별도로 관리합니다.":
      "Android versions with advertising enabled may show a Google AdMob banner at the bottom of Home to free users. Ads are not shown during a subscription or its free trial. Ads are not placed on letter-writing, garden walk, or meditation screens.\n\nThe app requests non-personalized ads. It does not send letter text, selected emotions, mood scores, tree memories, friend codes, or sign-in accounts as ad-targeting data. Even with non-personalized ads, Google's advertising SDK may process IP addresses, ad interactions, diagnostics, and device identifiers to deliver and measure ads and prevent misuse. Non-personalized advertising does not mean that no data is collected.\n\nAn advertising privacy choices screen is provided where required. In versions with advertising enabled, view or change your choices under My account → Ad privacy choices. Usage sharing and ad privacy choices are managed separately.",
  "문의": "Contact us",
  "일반 문의, 개인정보 문의 또는 계정 삭제 요청은 아래 이메일로 문의해 주세요.\n\n{0}":
      "For general questions, privacy questions, or account deletion requests, contact the email address below.\n\n{0}",
  "처리 위탁·국외 처리·삭제 안내": "Service providers, international processing & deletion",
  "Firebase·Google Cloud와 로그인·광고 제공사의 서비스에서 정보를 처리합니다. 서버 함수는 서울 리전으로 구성되어 있으나 인증·광고·통계 및 지원 과정의 처리 국가가 모두 한국이라는 뜻은 아닙니다. 제공사별 수탁자·처리 국가·이전 항목과 시점·방법·보유 기간은 운영 계약 확인 후 공개 방침에 확정해야 합니다.\n\n기기 기록은 직접 삭제하거나 앱 데이터를 지울 때까지 보관합니다. 설정·이용 카운터 등 일부 보조 정보는 앱 전용 저장소에 보관되며 모두 별도 암호화되는 것은 아닙니다. 앱 재설치 시 자동 복원을 보장하지 않으며, 직접 만든 암호화 백업과 암호가 필요합니다.\n\n기록 보관과 백업에서 서버 계정 삭제를 요청할 수 있습니다. 로그아웃은 삭제가 아닙니다. 기기 기록·내보낸 파일의 삭제와 Google Play 구독 해지는 별도로 진행해야 합니다. 앱 없이도 아래 웹 링크에서 이메일로 계정·데이터 삭제를 요청할 수 있습니다. 이메일 작성만으로 자동 전송되거나 삭제되지는 않습니다. 처리 기한과 신고·운영 로그의 보유 기간은 정식 출시 전 확정해야 합니다.":
      "Information is processed through Firebase, Google Cloud, and sign-in and advertising providers. Server functions are configured in the Seoul region, but this does not mean all authentication, advertising, analytics, or support processing takes place in Korea. Provider-specific processors, countries, transferred data, timing, methods, and retention periods must be finalized in the public policy after operational agreements are reviewed.\n\nDevice entries are kept until you delete them or clear app data. Some supporting data, such as settings and usage counters, is stored in app-specific storage and is not all separately encrypted. Automatic restoration after reinstalling is not guaranteed; you need your own encrypted backup and its password.\n\nRequest cloud account deletion in Storage & backup. Signing out is not deletion. Deleting device entries or exported files and canceling a Google Play subscription are separate steps. You can also use the web link below to request account and data deletion by email without the app. Writing an email does not automatically send it or delete data. Processing deadlines and retention periods for reports and operational logs must be finalized before public release.",
  "공개 개인정보처리방침": "Public privacy policy",
  "웹에서 계정·데이터 삭제 요청": "Request account & data deletion online",
  "현재 표시할 광고 개인정보 선택 화면이 없어요.":
      "There is no ad privacy choices screen available right now.",
  "데이터 처리 안내 · 2026.10.31 테스트 운영":
      "Data processing information · Test operation, October 31, 2026",
  "꼭 읽어주세요 · 정신건강 안내": "Please read · Mental health information",
  "마음냥 정원은 감정을 돌아보고 작은 실천으로 마음을 돌보는 것을 돕는 자기돌봄(self-care) 및 마음챙김 보조 앱입니다.\n\n이 앱은 의료 서비스가 아니며, 전문적인 진단·치료·상담을 대체할 수 없습니다. 앱에서 제공하는 감정 기록, 명상, 조언은 정서적 참고 자료일 뿐 의학적 조언이 아닙니다.\n\n만약 지속적으로 힘든 감정이 계속되거나, 스스로 또는 타인을 해치고 싶은 생각이 든다면 반드시 정신건강 전문가, 의료기관 또는 아래의 상담 기관에 도움을 요청해 주세요.\n\n· 자살예방상담전화 109 (24시간)\n· 정신건강상담전화 1577-0199 (24시간)\n· 청소년상담전화 1388":
      "Mindnyang Garden supports self-care and mindfulness through reflection and small, caring activities.\n\nIt is not a medical service and does not replace professional diagnosis, treatment, or counseling. Mood entries, meditation, and suggestions in the app are for personal reflection, not medical advice.\n\nIf difficult feelings persist, seek support from a mental health professional or healthcare service. If you may harm yourself or someone else, contact local emergency services or a crisis support service in your country. The Korean-language screen lists support services for South Korea; these are not worldwide contact numbers.",
