  "준비된 3개 주제, 각 4개의 이야기예요. 주 1편씩 또는 편한 속도로 만나보세요. 쉬었던 날의 벌점은 없어요.":
      "Three themes, with four stories each. Try one a week or go at your own pace. There is no penalty for taking a break.",
