  "마지막 답장 남기기": "Save your final reply",
  "다음 고양이에게": "Next cat",
  "이 앱은 어떤 생각에서 시작됐나요?": "What inspired this app?",
  "마음냥 정원은 심리학자 칼 융(Carl Jung)의 \"그림자(Shadow)\" 개념에서 출발했어요.\n\n융은 우리 마음속에는 스스로 인정하고 싶지 않아 밀어내 버린 감정이나 모습들이 있다고 말했어요. 슬픔, 질투, 무기력, 분노 같은 감정들이요. 이런 감정들은 없애야 할 \"나쁜 것\"이 아니라, 오히려 있는 그대로 바라보고 인정할 때 우리를 더 온전하게 만들어주는 \"그림자\"랍니다.\n\n이 앱은 그 그림자를 고양이의 모습으로 바꿔, 매일 조금씩 만나고 이야기 나누며 나 자신을 더 깊이 이해할 수 있도록 돕는 마음챙김 정원이에요.":
      "Mindnyang Garden draws on psychologist Carl Jung's concept of the shadow.\n\nJung described feelings and parts of ourselves that we may push away because they are hard to accept—such as sadness, jealousy, low energy, or anger. The idea behind the garden is to make room for these feelings rather than treat them as bad things to eliminate.\n\nHere, those feelings take the form of cats. Meeting them and writing a little can give you a gentle space to reflect and understand yourself.",
  "37마리 고양이는 무슨 의미인가요?": "What do the 37 cats represent?",
  "정원에는 총 37마리의 그림자 고양이가 살고 있어요. 각 고양이는 슬픔, 질투, 분노, 불안, 외로움처럼 우리가 자주 느끼지만 쉽게 드러내지 못하는 감정부터, 행복, 다정함, 만족, 평온처럼 소중히 간직하고 싶은 감정까지 사람이 느낄 수 있는 다양한 마음의 스펙트럼을 하나씩 대표하고 있어요.\n\n한 가지 감정만으로는 사람의 마음을 다 담을 수 없기에, 37가지로 나누어 오늘 내 마음과 가장 닮은 고양이를 찾을 수 있게 했어요. 각 고양이에게는 왜 그런 감정을 느끼는지 이야기가 있고, 그 감정을 다정하게 안아주는 위로의 말과, 오늘 해볼 수 있는 작은 실천 지침이 함께 담겨 있어요.":
      "The garden is home to 37 mood cats. They represent a range of feelings, from sadness, jealousy, anger, anxiety, and loneliness to happiness, tenderness, contentment, and calm.\n\nNo single feeling captures everything about a person. Choose the cat that feels closest to you today. Each cat has a story, a few comforting words, and a small activity you might like to try.",
  "앱에서는 어떤 걸 할 수 있나요?": "What can I do in the app?",
  "왜 매일 감정을 기록해야 하나요?": "Why keep a record of my feelings?",
  "오늘의 감정과 닮은 고양이를 직접 고르고 편지를 쓰며 내 경험을 돌아볼 수 있어요.\n\n오늘의 고양이 카드는 무작위로 뽑는 재미용 카드예요. 심리 검사나 무의식 분석, 미래 예측이 아니에요. 같은 카드가 반복되거나 내가 고른 고양이와 같아도 우연일 수 있어요.\n\n카드 이야기에서 마음에 와닿는 부분만 골라 보세요. 맞지 않으면 그냥 넘겨도 괜찮아요. 내 마음은 내가 정해요.":
      "Choose a cat that reflects how you feel and write a letter to explore your own experience.\n\nToday's cat card is a playful random draw, not a psychological test, an analysis of your unconscious, or a prediction. A repeated card—or one that matches your chosen cat—may simply be a coincidence.\n\nTake only what resonates from its story. If it doesn't fit, you can skip it. You know your own feelings best.",
  "마음냥 정원과 함께, 오늘의 마음을 천천히 들여다보세요 🌙":
      "Take your time with today's feelings in Mindnyang Garden 🌙",
  "마음냥 정원에 오신 걸 환영해요": "Welcome to Mindnyang Garden",
  "이 화면에서는 이 앱이 어떤 생각에서 시작됐는지, 37마리 고양이는 어떤 의미인지, 그리고 앱에서 무엇을 할 수 있는지 차근차근 소개해드려요.":
      "Explore the ideas behind the garden, meet its 37 cats, and discover what you can do here.",
  "오늘의 감정 고양이 만나기": "Meet today's mood cat",
  "지금 내 기분과 가장 닮은 고양이를 37마리 중에서 직접 골라보세요.":
      "Choose the cat that best matches how you feel from the 37 mood cats.",
  "고양이에게 편지쓰기": "Write to a cat",
  "고른 고양이에게 하고 싶은 말을 편지로 남기며, 감정을 있는 그대로 들여다봐요.":
      "Write to the cat you chose and give your feelings a little space, just as they are.",
  "오늘의 고양이 카드 (카드뽑기)": "Today's cat card · Random draw",
  "오늘의 고양이 카드를 무작위로 한 장 뽑아보고, 위로와 실천 지침을 받아보세요.":
      "Draw a cat card at random for a little comfort and a small idea to explore.",
  "밥 주기 · 물 주기 · 목욕 · 청소로 나만의 아기고양이를 함께 키워나가요.":
      "Raise your kitten with food, water, baths, and a little cleaning.",
  "명상 · 움직임 가이드": "Meditation & movement guides",
  "호흡법, 스트레칭, 걷기 명상 등 오늘의 감정에 어울리는 이완 가이드를 만나보세요.":
      "Explore breathing, stretching, or mindful walking practices that may fit how you feel today.",
  "마음 온도 기록 · 리포트": "Care warmth & reports",
  "그동안 쌓인 감정과 기록을 그래프와 월간 리포트로 돌아볼 수 있어요.":
      "Look back at your entries and feelings through charts and monthly reports.",
  "지금 마음은 얼마나 편안한가요?": "How comfortable do you feel right now?",
  "1 매우 힘들어요 · 10 매우 편안해요\n진단 점수가 아니라 내가 느끼는 정도예요.":
      "1 Very uncomfortable · 10 Very comfortable\nThis reflects how you feel, not a diagnostic score.",
  "지금은 모르겠어요 · 선택 안 함": "I'm not sure right now · Skip",
  "점수 선택 지우기": "Clear my score",
  "작성 중인 기록을 닫을까요?": "Close this draft?",
  "아직 저장하지 않은 내용은 사라져요.": "Anything you haven't saved will be lost.",
  "계속 쓰기": "Keep writing",
  "내 마음을 저장했어요.": "Your reflection is saved.",
  "저장했어요. 해본 뒤 기록에서 도움 여부를 남겨 주세요.":
      "Saved. After trying it, you can record whether it helped.",
  "저장하지 못했어요. 내용은 그대로 있으니 다시 시도해 주세요.":
      "Couldn't save. Your words are still here—please try again.",
  "내 마음 돌보기": "Care for myself",
  "마음 알아차리기": "Notice how you feel",
  "잠깐 돌아보기": "Take a moment to reflect",
  "작은 돌봄 고르기": "Choose a small act of care",
  "이름 붙이고 싶은 감정 · 선택": "Name a feeling, if you'd like",
  "감정 이름은 나중에 정할래요": "I'll name it later",
  "답할 수 있는 질문 하나만 골라요.": "Choose just one question you feel able to answer.",
  "한 줄도 괜찮아요. 잘 모르겠다면 비워 두세요.":
      "One line is enough. It's okay to leave it blank.",
  "아직 이유를 설명하거나 감정을 바꾸지 않아도 괜찮아요.":
      "You don't have to explain or change your feelings yet.",
  "지금 해보고 싶은 게 있나요?\n고르는 것만으로 완료 처리되지는 않아요.":
      "Is there something you'd like to try?\nChoosing it won't mark it as completed.",
  "오늘은 기록만 남길래요": "Just save my reflection today",
  "나에게 남길 한 줄 · 선택": "A line for myself · Optional",
  "예: 퇴근 뒤 5분 쉬어보기": "For example: Rest for five minutes after work",
  "이 기록은 내 기기에 저장되고 기존 암호화 백업에 포함돼요.\n기관이나 이웃에게 자동으로 공유되지 않아요.":
      "This entry stays on your device and is included in encrypted backups.\nIt isn't automatically shared with services or neighbors.",
  "저장 중…": "Saving…",
  "다음 · 비워 두어도 괜찮아요": "Next · It's okay to leave it blank",
  "내 기록 저장": "Save my entry",
  "이전": "Previous",
  "누군가의 도움이 필요해요": "I'd like some support",
  "작성 중인 후기를 닫을까요?": "Close this reflection?",
  "변경한 후기는 아직 저장되지 않았어요.": "Your changes haven't been saved yet.",
  "해본 뒤 돌아보기": "Reflect after trying it",
  "직접 해보았다면 어땠는지 남겨 주세요.\n점수가 오르지 않아도 괜찮아요. 아직 안 했다면 나중에 돌아와도 돼요.":
      "If you've tried it, write how it felt.\nYour score doesn't have to improve. If you haven't tried it yet, come back whenever you're ready.",
  "이 방법을 계속하지 않아도 괜찮아요. 다음에는 다른 돌봄을 선택할 수 있어요.":
      "You don't have to keep using this activity. You can choose something different next time.",
  "지금의 편안함도 남길까요? · 선택": "Record how comfortable you feel now? · Optional",
