  "날짜는 정원소식에서 확인해 주세요.": "Check Garden News for the date.",
  "모임 안내와 접속 링크 보기": "Event details and joining link",
  "제1조 (목적)": "Article 1: Purpose",
  "이 약관은 마음냥 정원(이하 \"앱\")을 이용함에 있어 이용자와 앱 운영자 사이의 권리, 의무 및 책임사항, 이용 조건 및 절차 등 기본적인 사항을 규정하는 것을 목적으로 합니다.":
      "These Terms set out the rights, obligations, responsibilities, conditions, and procedures governing your use of Mindnyang Garden (the “App”) and your relationship with its operator.",
  "제2조 (서비스의 성격)": "Article 2: About the service",
  "앱은 감정을 돌아보고 작은 실천으로 마음을 돌보는 것을 돕는 자기돌봄(self-care) 및 마음챙김 보조 도구입니다.\n\n앱은 의료 서비스가 아니며, 전문적인 진단·치료·상담을 대체하지 않습니다. 앱이 제공하는 감정 기록, 명상, 조언, 고양이 캐릭터의 메시지 등은 정서적 참고 자료일 뿐 의학적 조언으로 간주되지 않습니다.":
      "The App is a self-care and mindfulness tool designed to help you reflect on your feelings and care for yourself through small everyday actions.\n\nIt is not a medical service and does not replace professional diagnosis, treatment, or counseling. Emotion journals, meditations, suggestions, and messages from cat characters are provided for reflection and emotional support, not as medical advice.",
  "제3조 (이용자의 의무)": "Article 3: Your responsibilities",
  "이용자는 다음 각 호의 행위를 하지 않아야 합니다.\n\n· 앱의 정상적인 운영을 방해하는 행위\n· 괴롭힘·혐오·성적 콘텐츠·폭력 위협·스팸·사기 게시\n· 타인의 개인정보 또는 권리를 침해하는 콘텐츠 공유\n· 타인의 개인정보를 무단으로 수집·저장하는 행위\n· 관계 법령 또는 이 약관에서 금지하는 행위\n\n공개·공유 기능을 사용하기 전 이 약관에 동의해야 합니다. 부적절한 콘텐츠나 사용자는 신고·차단할 수 있습니다. 운영자는 신고를 검토하여 공개 중단 또는 공유 이용 제한 등의 조치를 취할 수 있습니다. 개인 기록은 공개 동의와 관계없이 사용할 수 있습니다.":
      "You must not:\n\n· Disrupt the normal operation of the App\n· Post harassment, hate, sexual content, threats of violence, spam, or scams\n· Share content that infringes another person’s privacy or rights\n· Collect or store another person’s personal information without permission\n· Engage in conduct prohibited by applicable law or these Terms\n\nYou must agree to these Terms before using public or sharing features. You can report or block inappropriate content and users. The operator may review reports and remove public content or restrict sharing. You can use your private journal without agreeing to public sharing.",
  "제4조 (유료 서비스)": "Article 4: Paid services",
  "앱은 일부 기능을 유료 구독(프리미엄) 형태로 제공할 수 있습니다. 유료 서비스의 구체적인 가격, 결제 방법, 환불 정책은 앱 내 결제 화면 및 이용하시는 앱 마켓(Google Play 등)의 정책에 따릅니다.\n\n유료 서비스가 실제로 제공되기 전까지, 관련 화면에는 정확한 이용 가능 여부가 안내됩니다.":
      "Some features may be offered through a paid premium subscription. Prices, payment methods, and refunds are governed by the in-app purchase screen and the policies of your app marketplace, such as Google Play.\n\nUntil a paid service is available, its availability will be clearly indicated on the relevant screen.",
  "제5조 (서비스의 변경 및 중단)": "Article 5: Service changes and interruptions",
  "앱 운영자는 서비스의 내용, 운영상 또는 기술상 필요에 따라 제공 중인 서비스의 전부 또는 일부를 변경하거나 중단할 수 있으며, 이 경우 앱 내 공지 등을 통해 이용자에게 사전에 안내합니다.":
      "The operator may change or discontinue all or part of the service for operational or technical reasons. Users will be notified in advance through in-app announcements or other appropriate channels.",
  "제6조 (면책 조항)": "Article 6: Limitations of liability",
  "앱 운영자는 천재지변, 이용자의 귀책사유 등 불가항력적인 사유로 서비스를 제공할 수 없는 경우 책임이 면제됩니다.\n\n앱을 통해 얻은 정서적 조언이나 기록은 참고 자료이며, 이를 근거로 한 이용자의 판단과 행동에 대해 앱 운영자는 법적 책임을 지지 않습니다. 위급한 상황에는 반드시 전문가 또는 관련 기관(하단 참고)의 도움을 받으시기 바랍니다.":
      "The operator is not responsible for service interruptions caused by force majeure, including natural disasters, or circumstances attributable to the user.\n\nEmotional suggestions and records provided through the App are for reference. The operator does not accept legal responsibility for decisions or actions based on them. In an emergency, seek help from a qualified professional or an appropriate emergency service.",
  "제7조 (문의)": "Article 7: Contact",
  "일반 문의·개인정보 문의·계정 삭제 요청은 {0}으로 보내 주세요. 비밀번호나 인증번호는 보내지 마세요.":
      "For general questions, privacy inquiries, or account deletion requests, contact {0}. Never send your password or verification codes.",
  "커뮤니티 약관 버전: 2026-10-31": "Community Terms version: October 31, 2026",
