  "활동으로 차곡차곡 모은 온기를 살펴보세요":
      "See the care warmth you've earned through your activities",
  "내가 남긴 감정과 회고 보기": "View my feelings and reflections",
  "최근 7일": "Last 7 days",
  "최근 30일": "Last 30 days",
  "아직 저장된 돌봄 온기가 없어요": "No care warmth saved yet",
  "이 기록의 의미": "What this record means",
  "내 감정을 돌아보려면": "Looking back on your feelings",
  "{0} 온기 구간": "{0} warmth range",
  "저장된 {0}일의 온기 값을 숫자 구간으로 나눴어요":
      "Warmth values from {0} saved days, grouped into ranges",
  "구간은 마음의 좋고 나쁨을 뜻하지 않아요. 하루의 마지막 온기 값을 표시하며, 보상 적립 후 0부터 다시 쌓인 날도 포함돼요.":
      "These ranges don’t mean your feelings were good or bad. Each day shows its final warmth value, including days when warmth started building again from zero after a reward.",
  "날짜별 돌봄 온기 (0~100)": "Daily care warmth (0–100)",
  "최근 {0}개의 저장 값을 표시해요. 색은 온기 값의 구간이에요. 보상 적립으로 값이 줄어들 수 있어 감정의 변화로 해석하지 않아요.":
      "Showing the {0} most recent saved values. Colors represent warmth ranges. Rewards can reduce the value, so these changes should not be interpreted as changes in your emotions.",
  "돌봄 기록을 불러오지 못했어요. 기록을 지우지 않고 다시 시도할 수 있어요.":
      "We couldn’t load your care records. You can try again without deleting anything.",
  "저장을 마치지 못했어요. 다시 시도해 주세요.": "We couldn’t finish saving. Please try again.",
  "나에게 맞는 작은 돌봄": "Find a way to care for yourself",
  "계획만 남겨도 괜찮아요. 실제로 해본 뒤 따로 표시할 수 있어요.":
      "It’s okay to leave this as a plan. You can mark it as tried whenever you’re ready.",
  "해보고 싶은 돌봄": "Something I’d like to try",
  "예: 창가에서 차 한 잔 마시기": "For example: Have a cup of tea by the window",
  "어떤 때를 위한 건가요? · 선택": "When might this help? · Optional",
  "관계": "Relationships",
  "일·공부": "Work or study",
  "몸이 피곤할 때": "When my body feels tired",
  "이유를 모르겠을 때": "When I’m not sure why",
  "계획 남기기": "Save a plan",
  "해보고 싶은 돌봄을 남겼어요. 편한 때 해보세요.":
      "Your plan is saved. Try it whenever it feels right.",
  "실제로 해보셨나요?": "Have you tried it?",
  "해본 뒤 어땠나요?": "How did it feel?",
  "내가 느낀 만큼만 남겨주세요. 도움 여부를 고르지 않아도 돼요.":
      "Share as much as you’d like. You don’t have to say whether it helped.",
  "해봤다는 것만 남기기": "Just mark it as tried",
  "내가 남긴 경험을 저장했어요.": "Your experience is saved.",
  "이 돌봄 기록을 지울까요?": "Delete this care record?",
  "돌봄 목록에서 지워져요. 원래 쓴 편지와 정원의 성장은 유지돼요.":
      "It will be removed from your care list. Your original letter and garden growth will stay.",
  "지우기": "Delete",
  "돌봄 기록을 지웠어요.": "Care record deleted.",
  "잠깐 명상하기": "Take a meditation break",
  "{0}월 {1}일": "{0}/{1}",
  "돌봄 기록 지우기": "Delete care record",
  "{0} 계획{1}": "{0} · Planned{1}",
  "{0} 해봤어요 · {1}": "{0} · Tried · {1}",
  "해봤어요": "Tried it",
  "다시 돌아보기": "Reflect again",
  "명상 고르기": "Choose a meditation",
  "두 달의 돌봄 돌아보기": "Look back on two months of care",
  "정원 플러스에서는 지난달과 이번 달에 직접 남긴 돌봄 경험을 나란히 볼 수 있어요. 기존 기록 열람과 기본 통계는 무료예요.":
      "Garden Plus lets you view the care experiences you recorded last month and this month side by side. Your existing records and basic statistics remain free.",
  "정원 플러스 알아보기": "Explore Garden Plus",
  "지난달 · 해본 돌봄 {0}회 / 도움이 됐다고 남긴 경험 {1}회":
      "Last month · Tried {0} times / Marked helpful {1} times",
  "이번 달 · 해본 돌봄 {0}회 / 도움이 됐다고 남긴 경험 {1}회":
      "This month · Tried {0} times / Marked helpful {1} times",
  "기록한 횟수이며 효과나 마음의 개선 점수가 아니에요. 기록이 없는 날은 계산하지 않아요.":
      "These are counts of your records, not measures of effectiveness or emotional improvement. Days without records aren’t included.",
  "나에게 도움이 됐던 것을\n필요한 날 다시 꺼내요.":
      "Keep what helped close,\nfor the days you need it.",
  "내가 직접 남긴 경험만 모아요. 쉬어간 날에는 벌점도, 해야 할 숙제도 없어요.":
      "Only experiences you choose to record appear here. Days off bring no penalties and no homework.",
  "필요한 날 다시 꺼내요": "Here when you need it",
  "간직한 말 다시 보기": "Revisit words you’ve kept",
  "도움이 됐던 돌봄 꺼내기": "Revisit care that helped",
  "지금 나에게 해줄 작은 일": "One small thing I can do for myself",
  "마음의 온도 · 주간·월간 통계": "Care warmth · Weekly and monthly statistics",
  "이번 주, 내가 남긴 경험": "Experiences I recorded this week",
  "해본 돌봄 {0}회 · 도움 여부를 남긴 경험 {1}회":
      "Activities tried: {0} · Reflections: {1}",
  "아직 남긴 경험이 없어요. 계획만 골라도 괜찮아요.":
      "No experiences recorded yet. It’s okay to start with just a plan.",
  "그중 {0}회는 도움이 됐다고 남겼어요.": "You marked {0} of those as helpful.",
  "느낌이 그대로여도 소중한 기록이에요. 다음에 해보고 싶은 작은 일을 골라보세요.":
      "Even if your feelings haven’t changed, your experience matters. Choose one small thing you might like to try next.",
  "나에게 도움이 됐던 돌봄": "Care that helped me",
  "직접 해보고 도움이 됐다고 남기면 여기에 모여요.":
      "Things you’ve tried and marked as helpful will appear here.",
  "{0} · 내가 도움이 됐다고 남긴 경험": "{0} · An experience I marked as helpful",
  "다시 해볼 계획 남기기": "Plan to try it again",
  "편한 때 해보고 싶은 돌봄": "Things I'd like to try",
  "간직한 말": "Words I’ve kept",
  "편지에서 직접 고른 문장과 저장한 응원을 모아볼 수 있어요.":
      "Find sentences you chose from your letters and encouragement you saved.",
  "간직한 말이 담긴 기록 {0}개가 있어요.": "{0} records contain words you’ve kept.",
  "내 문장 · 나에게 한 말 · 받은 응원 보기":
      "My words · Words to myself · Encouragement received",
  "해본 돌봄 기록": "Care I’ve tried",
  "이 기록은 나의 경험을 돌아보기 위한 것이며 진단이나 치료 효과를 나타내지 않아요.":
      "These records help you reflect on your own experiences. They do not indicate a diagnosis or treatment outcome.",
  "직접 열 수 있는 주소": "Open link",
  "원할 때, 사람과 연결": "Connect with someone when you’re ready",
  "혼자 돌아보는 것만으로 충분하지 않을 때":
      "When reflecting on your own doesn’t feel like enough",
  "어떤 도움을 받을지는 내가 선택해요. 점수와 관계없이 이용할 수 있어요.\n일상생활이 어려울 만큼 힘든 상태가 계속된다면 전문기관에 상담을 요청할 수 있어요.":
      "You choose the support that feels right for you, regardless of any score.\nIf distress continues to make everyday life difficult, you can reach out to a qualified professional.",
  "지역 정신건강복지센터": "Community mental health centers in South Korea",
  "공식 기관 정보를 확인하고 상담 방법을 문의할 수 있어요. 정신건강사회복지사 등 전문요원과의 상담·생활 지원이 가능한지 기관에 물어보세요. 운영시간과 이용 대상은 기관마다 달라요.":
      "Visit the official directory to ask about counseling and support for everyday life, including services from mental health social workers. Opening hours and eligibility vary by center.",
  "공식 기관 안내 열기": "Open the official directory",
  "심리상담센터": "Counseling services",
  "내 이야기를 전문 상담자와 나누고 싶을 때 찾아볼 수 있어요. 예약 전에 상담자의 자격·경력, 상담 분야, 비용과 취소 규정을 확인해 주세요.":
      "A place to talk with a professional counselor. Before booking, check their qualifications, experience, areas of practice, fees, and cancellation policy.",
  "지도에서 심리상담센터 검색": "Find counseling services on a map",
  "명상센터 · 마음챙김 모임": "Meditation centers and mindfulness groups",
  "명상이나 쉼을 함께 경험하고 싶을 때 찾아볼 수 있어요. 진행자, 프로그램, 참가 비용을 확인하고 나에게 불편한 활동은 중단할 수 있어요. 명상 프로그램은 전문 진료를 대신하지 않아요.":
      "Explore shared meditation or rest. Check the facilitator, program, and cost, and stop any activity that feels uncomfortable. Meditation programs do not replace professional medical care.",
  "지도에서 명상센터 검색": "Find meditation centers on a map",
  "명상센터": "Meditation center",
  "현재는 기관 정보와 지도 검색을 연결해요. 마음냥의 제휴·자격 검증·예약 확정을 뜻하지 않아요. 신청과 예약은 해당 기관에서 직접 진행해 주세요.":
      "These links provide information and map searches only. They do not mean Mindnyang has partnered with a provider, verified qualifications, or confirmed a booking. Contact the provider directly to register or book.",
  "기관에 마음 기록을 자동으로 보내지 않아요. 외부 사이트를 열면 해당 서비스의 개인정보처리방침이 적용돼요. 지도에는 기관 종류만 검색어로 전달돼요.":
      "Your journal is not sent to these providers automatically. External sites have their own privacy policies. Map searches only receive the type of service as a search term.",
  "지금 안전이 걱정된다면 · 대한민국": "If you’re worried about your safety · South Korea",
  "자살 생각으로 힘들 때는 24시간 상담전화 109를 이용할 수 있어요. 즉각적인 위험이나 응급상황에는 112·119에 연락해 주세요.":
      "If you’re in immediate danger, contact your local emergency services. For emotional crisis support, use the resources for your country below. The Korean-language screen lists South Korea’s crisis and emergency contacts.",
  "{0} 전화": "Call {0}",
  "대한민국 밖에서 도움 찾기": "Find support outside South Korea",
  "기록집을 불러오지 못했어요. 다시 시도해 주세요.":
      "We couldn’t load your keepsakes. Please try again.",
  "기록집으로 남길 달을 골라 주세요": "Choose a month for your keepsake",
  "이 달 선택": "Choose this month",
  "여러 달의 기록집을 나란히 돌아보는 기능이에요. 기존 기록집은 무료로 계속 볼 수 있어요.":
      "Compare keepsakes from different months side by side. You can continue viewing your existing keepsakes for free.",
  "정원에 쌓인 시간": "Moments from your garden",
  "직접 골라 담은 기록을 달마다 돌아봐요. 기록의 개수는 마음의 점수가 아니에요.":
      "Revisit the records you chose to keep, month by month. The number of records isn’t a score for your feelings.",
  "{0} · {1}개의 문장, {2}개의 돌봄": "{0} · {1} sentences, {2} care experiences",
  "선택해 담은 돌봄이 없어요.": "No care experiences selected.",
  "이 달 펼쳐보기": "Open this month",
  "월간 정원 기록집": "Monthly garden keepsakes",
  "내가 고른 문장과 도움이 된 경험을 한 달의 정원에 담아요.":
      "Make a monthly keepsake with your favorite words and activities that helped you.",
  "첫 기본 기록집은 무료예요. 새 달의 기록집과 계절 표지는 구독으로 만들 수 있어요. 이미 만든 기록집은 해지 후에도 열람·수정·공유할 수 있어요.":
      "Your first keepsake with a standard cover is free. A subscription lets you create keepsakes for new months and use seasonal covers. Keepsakes you’ve already made remain available to view, edit, and share after cancellation.",
  "{0}의 마음 다시 보기": "Revisit {0}",
  "선택한 달의 기록집을 열거나 새로 만들 수 있어요.":
      "Open or create a keepsake for your chosen month.",
  "담을 달 고르기": "Choose a month",
  "여러 달 함께 돌아보기 · 구독": "Compare months · Subscription",
  "아직 기록집이 없어요. 남기고 싶은 달부터 천천히 만들어 보세요.":
      "No keepsakes yet. Start with a month you’d like to remember, whenever you’re ready.",
  "{0}의 정원": "{0} garden",
  "내 문장 {0} · 돌봄 {1}\n{2}에 저장": "My words: {0} · Care: {1}\nSaved {2}",
