      "We couldn’t load your records. Your existing records are still safe.",
  "문장은 세 개까지 고를 수 있어요.": "You can choose up to three sentences.",
  "내 문장 그대로 담기": "Keep my own words",
  "위 편지에서 남길 부분을 복사하거나 그대로 적어 주세요.":
      "Copy or type the words you’d like to keep from the letter above.",
  "기록집에 담을 문장": "A sentence for your keepsake",
