  "기본 표지": "Standard cover",
  "계절 표지 · 구독": "Seasonal cover · Subscription",
  "첫 기본 기록집은 무료예요. 이후 새 달의 기록집과 계절 표지는 구독이 필요해요. 기존 기록집의 내용은 해지 후에도 다듬을 수 있어요.":
