  "공유하지 못했어요. 다시 시도해 주세요.": "We couldn’t share this. Please try again.",
  "이 기록집을 지울까요?": "Delete this keepsake?",
  "기록집과 여기에 나중에 남긴 말이 지워져요. 원래 편지와 정원은 그대로예요. 첫 무료 기록집을 삭제해도 무료 생성 기회가 다시 생기지는 않아요.":
