  "각 기록에서 직접 고른 감정을 모았어요. 선택 항목이 달라 출처별로 구분하며, 돌봄 온기나 게임 점수는 포함하지 않아요.":
      "These are the feelings you selected in each record. Sources are shown separately because their choices differ. Care warmth and game scores are not included.",
  "직접 남긴 감정 강도 평균 {0}/5": "Average emotion intensity you recorded: {0}/5",
  "강도를 입력한 정원 일기 {0}개만 계산했어요. 편지나 강도 미입력 기록은 평균에 넣지 않아요. 강도는 감정의 좋고 나쁨이나 건강 점수가 아니에요.":
      "Based only on {0} garden journal entries with an intensity rating. Letters and unrated entries aren’t included. Intensity is not a measure of how good or bad a feeling is, or a health score.",
  "감정 달력": "Mood calendar",
  "날짜별 기록": "Records by date",
  "날짜를 누르면 그날의 모든 기록을 볼 수 있어요.":
      "Tap a date to see all your records for that day.",
  "아이콘은 그날 남긴 감정 중 하나예요. 시간 없이 저장된 정원 일기도 있어 순서를 추정하지 않아요. 빈칸은 기록이 없는 날이에요.":
      "Each icon represents one feeling recorded that day. Some garden entries have no saved time, so we don’t assume their order. Blank dates have no records.",
  "이번 주의 대표 감정": "A feeling from this week",
  "기록이 아직 없어요.": "No records yet.",
  "상세 주간·월간 분석은 마음냥 구독으로 이용해요.":
