  "1 매우 힘들어요 · 10 매우 편안해요\n하루에 여러 번 남긴 점수는 일평균으로 묶어요. 기록 없는 날은 계산에서 제외하며, 실천 후 점수는 별도로 보관해요.":
      "1 Very distressed · 10 Very comfortable\nMultiple ratings on one day are averaged for that day. Days without records are excluded. Ratings after trying care are kept separately.",
