  "초안 불러오기": "Load draft",
  "함께 편지 쓰는 저녁": "An evening of writing together",
  "약 20분 동안 각자의 속도로 편지를 쓰고 정원에서 쉬어요.\n\n오늘의 질문: 지금 내 마음에 남아 있는 것은 무엇인가요?\n\n카메라 켜기와 편지 내용 공유는 필요하지 않아요. 듣기만 하거나 중간에 쉬어도 괜찮아요.\n이 모임은 함께 기록하는 시간이며 개인 상담이나 치료를 제공하지 않아요.":
      "Spend about 20 minutes writing at your own pace, then rest in the garden.\n\nToday's prompt: What's been on my mind lately?\n\nYou don't need to turn on your camera or share your letter. You're welcome to listen or take a break.\nThis is shared journaling time, not individual counseling or treatment.",
  "정원소식 수정": "Edit Garden News",
  "정원소식 작성": "Create Garden News",
  "저장하기": "Save",
  "저장하면 정원소식에 공개돼요.": "Saving publishes this in Garden News.",
  "제목": "Title",
  "내용": "Description",
  "함께 편지 쓰는 저녁 · 초안 불러오기": "An evening of writing together · Load draft",
