  "아직 정원에 아무도 없어요. 첫 고양이를 만나 정원을 채워보세요":
      "Your garden is waiting for its first cat. Meet one to begin filling it with life.",
  "지금까지 만난 고양이들이 정원 곳곳에 자리를 잡았어요":
      "The cats you’ve met have found little places throughout your garden.",
  "오늘의 고양이 만나러 가기 →": "Meet today’s cat →",
  "고양이 이미지": "Cat image",
  "{0}번째 만남": "Meeting {0}",
  "아직 만나지 않은 고양이": "A cat you haven’t met yet",
  "이 고양이는 아직 정원에 나타나지 않았어요.\n오늘의 감정 체크에서 만나볼 수 있어요.":
      "This cat hasn’t appeared in your garden yet.\nYou might meet them in today’s emotion check-in.",
  "오늘의 고양이 만나러 가기": "Meet today’s cat",
  "저장된 그림을 불러오지 못했어요. 다시 열어주세요.":
      "We couldn’t load your saved artwork. Please open it again.",
  "저장하지 못했어요. 다시 시도해주세요.": "We couldn’t save. Please try again.",
  "작품을 보관했어요. 모든 영역을 칠하면 오늘의 색칠 카드를 받을 수 있어요.":
      "Artwork saved. Color every area to receive today’s coloring card.",
  "계정이 바뀌었어요.": "Your account has changed.",
  "작품을 보관했어요. 오늘의 색칠 카드는 이미 받았어요.":
      "Artwork saved. You’ve already received today’s coloring card.",
  "작품 보관 완료! 추억 카드 한 장도 받았어요.":
      "Artwork saved! You also received a memory card.",
  "작품은 보관했어요. 로그인과 서버 연결을 확인한 뒤 완료를 다시 눌러 카드를 받아주세요.":
      "Artwork saved. Check your sign-in and connection, then tap Done again to claim your card.",
  "작품을 보관하지 못했어요. 다시 시도해주세요.":
      "We couldn’t save your artwork. Please try again.",
  "도안마다 가장 최근 완성한 작품을 보관해요.":
      "Your most recently completed artwork is kept for each design.",
  "완성한 작품을 여기에 모아드릴게요.": "Your finished artwork will gather here.",
  "마음냥 정원에서 색칠한 나의 작은 쉼":
      "Taking a coloring break in Mindnyang Garden",
  "그림 내보내기를 다시 시도해주세요.": "Please try exporting your artwork again.",
  "오늘은 어떤 색으로 쉬어갈까요?": "What colors would feel good today?",
  "영역을 톡 눌러 색칠해요. 두 손가락으로 확대할 수 있어요.":
      "Tap an area to color it. Pinch with two fingers to zoom.",
  "되돌리기를 저장하지 못했어요.": "We couldn’t save the undo action.",
  "전체보기": "Fit to screen",
  "보관한 작품 · 카드 받기 확인": "Saved artwork · Check card reward",
  "내 작품으로 보관했어요. 위 도안을 누르면 다시 볼 수 있어요.":
      "Your artwork is saved. Tap the design above to see it again.",
  "칠할 때마다 이 기기에 저장돼요. 완성하지 않아도 괜찮아요.":
      "Each stroke is saved on this device. You don’t have to finish.",
  "기본 도안 3종 · 무료. 색칠 카드는 모든 영역을 채우면 하루 한 장 받을 수 있어요.":
      "Three standard designs are free. Color every area to earn one coloring card per day.",
  "냠냠, 고마워요!": "Yum, thank you!",
  "{0} 1개를 맛있게 먹었어요.": "Enjoyed one {0}.",
  "쓰담쓰담": "Gentle pats",
  "{0} {1}개를 창고에 담았어요!": "Added {1} {0} to your storehouse!",
  "물을 주었어요. 열매가 쑥쑥 자라요.": "Watered! Your fruit is growing.",
  "{0}를 심었어요.": "Planted {0}.",
  "{0} {1}개를 선물했어요.": "Sent {1} {0} as a gift.",
  "정원 코인 {0}개를 모았어요.": "Collected {0} garden coins.",
