  "먼저 냥이 마을에서 이웃을 맺어 주세요.": "Add a neighbor in Cat Village first.",
  "선물할 이웃을 골라 주세요": "Choose a neighbor to send a gift to",
  "{0} 판매": "Sell {0}",
  "{0}님에게 선물": "Gift to {0}",
  "창고에 {0}개 있어요.": "You have {0} in your storehouse.",
  "수량 줄이기": "Decrease quantity",
