  "정원 코인 {0}개를 받아요.": "You’ll receive {0} garden coins.",
  "내 창고에서 차감되어 이웃 창고에 들어가요.":
      "These will move from your storehouse to your neighbor’s.",
  "판매하기": "Sell",
  "선물 보내기": "Send gift",
  "열매 정원 · 창고": "Orchard & storehouse",
  "새로고침 · 이전 요청 확인": "Refresh · Check previous request",
  "열매 나무 5종": "Five kinds of fruit trees",
  "정원 코인 {0}개": "{0} garden coins",
  "나무 돌보기": "Tend trees",
  "수확 창고": "Harvest storehouse",
  "묘목 상점": "Sapling shop",
  "나무와 수확물을 계정에 안전하게 보관해요.":
      "Your trees and harvests are stored safely in your account.",
  "다시 확인하기": "Check again",
  "우리 나무를 불러오고 있어요…": "Loading your trees…",
  "좌우로 넘겨 우리 나무를 만나세요": "Swipe left or right to visit your trees",
  "열매 {0}개가 익었어요!": "{0} fruits are ripe!",
  "예상 수확 {0}개 · 돌봄 {1}/5": "Expected harvest: {0} · Care: {1}/5",
  "물주기": "Water",
  "수확하기": "Harvest",
  "열매 나무는 구독 기능이며, 테스트에서는 사과나무 한 그루로 시작해요.\n기본 7일이면 익고, 물을 주면 12시간 더 빨리 자라요. 한국 시간 기준 하루 한 번, 최대 5번 돌보면 10개에서 30개까지 수확해요.\n접속하지 않아도 시들지 않고, 익은 열매는 사라지지 않아요.":
      "Fruit trees are a subscription feature. During testing, you start with one apple tree.\nFruit normally ripens in seven days. Watering speeds growth up by 12 hours. Water once per day, based on Korean time, up to five times to increase your harvest from 10 to 30 fruits.\nTrees won’t wilt while you’re away, and ripe fruit won’t disappear.",
  "수확물은 여기에 차곡차곡 쌓여요.": "Your harvests will gather here.",
  "{0}  {1}개": "{0} × {1}",
  "1개 판매 → 정원 코인 {0}개": "Sell one → {0} garden coins",
  "판매": "Sell",
  "이웃 선물": "Gift to a neighbor",
  "고양이에게 1개 주기": "Give one to my cat",
  "이웃에게 받은 선물 · 최근 30개": "Gifts from neighbors · Latest 30",
  "이웃이 보내준 열매도 이 창고로 들어와요.":
      "Fruit your neighbors send also arrives in this storehouse.",
  "{0}님이 보내준 선물": "A gift from {0}",
  "{0} {1}개": "{0} × {1}",
  "열매를 판매한 코인으로 새 묘목을 심어요.\n정원 코인은 묘목용이며 빛의 정수와 별도로 모아요. 현금 구매는 없어요.":
      "Sell fruit to earn coins for new saplings.\nGarden coins are only for saplings and are separate from Light Essence. They cannot be bought with real money.",
  "{0} 10~30개 · 한 종류당 한 그루": "{0}: 10–30 fruits · One tree of each kind",
  "우리 정원에서 자라는 중": "Growing in your garden",
  "{0}코인으로 심기": "Plant for {0} coins",
  "코드를 다시 확인해주세요": "Please check the code",
  "내 그림자 고양이 코드를 친구에게 보내보세요.\n친구가 코드를 입력하면 두 그림자가 나란히 놓여요.":
      "Share your mood cat code with a friend.\nWhen they enter it, you'll see your two mood cats side by side.",
  "아직 만난 고양이가 없어요": "You haven’t met a cat yet",
  "고양이를 먼저 만나면 내 코드가 만들어져요": "Meet a cat first to create your code",
  "코드를 복사했어요": "Code copied",
  "내 그림자 고양이는 '{0}'예요 🐾\n내 묘연 코드: {1}\n\n\"마음냥 정원\" 앱에서 이 코드를 입력하고\n네 그림자와 나란히 놓아볼래? #마음냥정원":
      "My mood cat is “{0}” 🐾\nMy cat code: {1}\n\nEnter it in Mindnyang Garden\nto see our mood cats together! #MindnyangGarden",
  "내 그림자 고양이": "My mood cat",
  "탭해서 코드 복사": "Tap to copy code",
  "친구에게 코드 보내기": "Send my code to a friend",
  "이 코드를 입력하고\n내 그림자와 나란히 놓아보세요": "Enter this code\nto meet my mood cat",
  "🐈‍⬛  마음냥 정원": "🐈‍⬛  Mindnyang Garden",
  "친구의 묘연 코드 입력하기": "Enter a friend's cat code",
  "예: M7K9": "For example: M7K9",
  "오늘의 묘연": "Our mood cats today",
  "나": "Me",
  "친구": "Friend",
  "오늘의 묘연: {0} × {1} 🐾 #마음냥정원":
      "Our mood cats today: {0} × {1} 🐾 #MindnyangGarden",
  "묘연 카드 공유하기": "Share our cat card",
  "다른 고양이 고르기": "Choose another cat",
  "오늘의 그림자\n방울 터뜨리기": "Today's feeling bubbles\nPop them when you're ready",
  "오늘 마주한 감정을 하나씩 가만히 들여다보고, 톡 터뜨려 놓아주세요":
      "Take a gentle look at today’s feelings, then tap to let them go.",
  "오늘의 감정을 먼저 기록해주세요": "Record today’s feelings first",
  "그림자 고양이에게 오늘의 마음을 들려주고 나면,\n그 감정이 담긴 방울들이 여기 조용히 피어나요":
      "Once you've shared how you feel with your mood cat,\nyour feelings will appear here as bubbles.",
  "이 마음은 지금 당장 다루지 않아도 괜찮아요":
      "You don’t have to work through this feeling right now.",
  "{0}에게 한마디 남기기": "A few words for {0}",
  "편지처럼 길게 쓰지 않아도 괜찮아요 · 짧은 한마디만 남겨보세요 (선택)":
      "It doesn’t need to be a whole letter. A few words are enough. (Optional)",
  "예) 오늘은 유난히 힘들었어": "For example: Today was especially hard.",
  "남기지 않기": "Skip",
  "한마디 남기기": "Leave a few words",
  "이 마음만은, 터뜨리지 않고\n잠시 땅에 묻어두어도 괜찮아요":
      "You can leave this feeling\nin the earth for a while instead of popping it.",
  "여기에 놓아주세요 🌱": "Leave it here 🌱",
  "🌿  방울을 여기로": "🌿  Bring a bubble here",
  "길게 눌러 드래그하면 묻어둘 수 있어요 · 하고 싶지 않다면 그냥 톡 터뜨려도 괜찮아요":
      "Touch and hold, then drag to bury a bubble. Or just tap to pop it—whatever feels right.",
  "오늘의 그림자 정원이\n조용히 정돈되었어요": "Your feeling garden\nis quiet for now.",
  "오늘 {0}개의 방울을 놓아주며\n포인트를 조금 모았어요 · 상점에서 꾸미기에 써보세요":
      "You let go of {0} bubbles today\nand gathered a few points to use on decorations in the shop.",
  "오늘 방울들을 모두 놓아주었어요": "You’ve let go of all today’s bubbles.",
  "땅에 묻어둔 마음 하나는 며칠 뒤,\n정원 어딘가에 작은 새싹으로 조용히 다시 찾아올 거예요":
      "In a few days, one feeling you buried\nwill return quietly as a little sprout somewhere in your garden.",
  "내일 새로운 감정을 기록하면,\n다시 새로운 방울들이 피어날 거예요":
      "Record new feelings tomorrow,\nand fresh bubbles will appear.",
  "함께 갈 고양이": "Choose a cat to bring along",
  "털색·성장 모습·고양이 이름만 이웃과 나눠요. 마음 기록은 공유하지 않아요.":
      "Only your cat’s coat, growth stage, and name are shared with neighbors. Your personal journal stays private.",
  "아기": "Kitten",
  "자라는 중": "Growing",
  "성묘": "Adult",
  "성장 중": "Growing",
  "열매 {0}개": "{0} fruits",
  "불러오지 못했어요 · 다시 시도": "Couldn’t load · Try again",
  "{0}에 간직했어요": "Kept on {0}",
  "내 편지에서 고른 문장": "Words I chose from my letter",
  "내가 나에게 남긴 말": "Words I left for myself",
  "{0}에게 받은 응원": "Encouragement from {0}",
  "그날 편지 보기": "Read that day’s letter",
  "나무에 간직하기": "Keep in a tree",
  "돌봄 목록에서 지우기": "Remove from my care list",
  "{0} · 내가 도움이 됐다고 남겼어요": "{0} · I marked this as helpful",
  "그때의 상황 · {0}": "What was happening · {0}",
  "내가 직접 간직한 말이에요. 나만 볼 수 있어요.": "Words you chose to keep, just for you.",
  "최근에 도움이 됐다고 남긴 경험이에요. 오늘도 맞을지 천천히 골라보세요.":
      "Experiences you recently marked as helpful. Take your time choosing what feels right today.",
  "내 문장": "My words",
  "나에게 한 말": "Words to myself",
  "받은 응원": "Encouragement received",
  "아직 간직한 말이 없어요. 편지에서 내 문장을 고르거나 받은 응원을 저장해 보세요.":
      "No words kept yet. Choose a sentence from a letter or save some encouragement you’ve received.",
  "아직 도움이 됐다고 남긴 돌봄이 없어요. 직접 해본 뒤 원하는 만큼만 남겨보세요.":
      "No care marked as helpful yet. After trying something, share as much or as little as you like.",
  "평가를 저장하지 못했어요. 다시 시도해 주세요.":
      "We couldn’t save your feedback. Please try again.",
  "이번 답장은 어땠나요? (선택)": "How did this reply feel? (Optional)",
  "내 마음과 맞아요": "It fits how I feel",
  "조금 달라요": "A little off",
  "반복적으로 느껴져요": "It feels repetitive",
  "평가는 이 기기에 저장되며 다음 답장의 표현 선택에 참고해요. 평가만으로 이미 받은 답장이 바뀌지는 않아요.":
      "Feedback is saved on this device and helps vary future replies. It won’t change a reply you’ve already received.",
  "정원 사진첩에 저장했어요.": "Saved to your garden album.",
  "사진을 저장하지 못했어요. 다시 시도해 주세요.": "We couldn’t save the photo. Please try again.",
