  "정원 별명과 공유 글은 다른 이용자에게 보여요. 괴롭힘·혐오·성적 콘텐츠·폭력 위협·스팸·사기·타인의 개인정보 공개를 금지합니다. 부적절한 내용은 신고·차단할 수 있고, 검토 후 공개 중단이나 공유 이용 제한이 적용될 수 있어요. 동의하지 않아도 개인 기록은 사용할 수 있어요.":
      "Your garden nickname and shared posts are visible to others. Harassment, hate, sexual content, threats of violence, spam, scams, and sharing someone else’s personal information are prohibited. You can report or block inappropriate content. After review, content may be removed or sharing restricted. You can use your private journal without agreeing.",
