  "알림 시간을 확인해 주세요.": "Please check the reminder time.",
  "조금 출출해졌어. 밥 먹고 같이 쉴까? 🐾":
      "I’m a little hungry. A bite to eat, then a rest together? 🐾",
  "나랑 잠깐 놀아 줄래? 장난감을 찾았어!": "Want to play for a moment? I found a toy!",
  "오늘은 네 손길이 좋아. 살짝 쓰다듬어 줄래?":
      "Got a moment for a little pet? Purr…",
  "내 옆에서 잠깐 쉬어 갈래? 오늘도 함께 있고 싶어.":
      "Want to rest beside me for a while? I’d love your company today.",
  "온기를 많이 모았어요": "Lots of care warmth",
  "온기가 차곡차곡 쌓였어요": "Care warmth is building",
