      "No server backup has been confirmed on this device. You can also use a file backup.",
  "마지막 서버 백업: {0}\n{1}": "Last server backup: {0}\n{1}",
  "아직 백업하지 않은 변경이 있어요. 백업·복원에서 지금 백업할 수 있어요.":
      "Some changes haven’t been backed up yet. Open Backup and Restore to back up now.",
  "최근 확인한 기록까지 백업했어요. 새 기록은 앱 사용 중 다시 확인해요.":
      "Records through the last check are backed up. New records are checked while you use the app.",
  "그 뒤 남긴 기록은 아직 백업되지 않았을 수 있어요.":
      "Records added since then may not be backed up yet.",
  "방문 고양이를 확인하지 못했어요.": "We couldn’t verify the visiting cat.",
  "초대장을 확인하지 못했어요.": "We couldn’t verify the invitation.",
