  "신청 내역을 다시 확인해 주세요.": "Please check your registrations again.",
  "기록집의 달을 확인해 주세요.": "Please check the keepsake month.",
  "기록집의 날짜가 올바르지 않아요.": "This keepsake’s date is invalid.",
  "기록집의 기억 날짜를 확인해 주세요.": "Please check the memory date.",
