  "추억": "Memories",
  "잊고 싶지 않은 하루를 담아요": "Keep a day you don’t want to forget",
  "황금빛": "Gold",
  "은빛": "Silver",
  "장밋빛": "Rose gold",
  "추억의 날짜와 내용을 확인해주세요.": "Please check the memory’s date and text.",
  "기억의 씨앗": "Memory seed",
  "작은 새싹": "Little sprout",
  "추억의 보석나무": "Memory gem tree",
  "기억의 나무 기록을 확인해주세요.": "Please check the memory tree record.",
  "씨앗과 성장 기록을 확인해주세요.": "Please check the seed and growth records.",
  "성장 날짜 순서가 달라요.": "Growth dates are out of order.",
  "추억이 중복돼요.": "This memory appears more than once.",
  "{0}엔 {1}가 자주 보였지만,\n{2}엔 아직 기록이 없어요.":
      "{1} appeared often in {0},\nbut there are no records for {2} yet.",
  "{0}엔 기록이 없었지만,\n{1}엔 {2}가 자주 보였어요.":
      "There were no records in {0},\nbut {2} appeared often in {1}.",
  "{0}과 {1} 모두,\n{2}가 가장 자주 나타났어요.":
      "In both {0} and {1},\n{2} appeared most often.",
  "{0}엔 {1}가,\n{2}엔 {3}가 가장 자주 나타났어요.":
      "{1} appeared most often in {0},\nand {3} in {2}.",
  "새벽": "early morning",
  "오전": "morning",
  "오후": "afternoon",
  "저녁": "evening",
  "최근 {0}일 동안 {1}요일 {2}에\n{3} 감정을 {4}번 기록했어요. 감정을 느낀 시간이 아닌 기록한 시간 기준이에요.":
      "Over the last {0} days, you recorded {3} {4} times\non {1}, in the {2}. This reflects when you recorded it, not when you felt it.",
  "(그날 남긴 짧은 문장은 따로 없어요)": "(No short note was left that day.)",
  "\n(이 기간 동안 총 {0}번 다시 떠올랐어요.)":
      "\n(It returned {0} times during this period.)",
  "묻어두었던 {0} 감정이 다시 떠올랐어요.\n그때는 \"{1}\"이었는데,\n지금은 \"{2}\"라고 적었어요.{3}":
      "The feeling you buried, {0}, returned.\nBack then, you wrote “{1}”.\nNow, you wrote “{2}”.{3}",
  "이 기간 동안, 묻어두었던 {0} 감정이\n총 {1}번 새싹으로 다시 떠올랐어요.":
      "During this period, the feeling you buried, {0},\nreturned as a sprout {1} times.",
  "정원 입구에 작은 방석을 놓았어. 오늘은 여기서 천천히 인사하자.":
      "I put a little cushion by the garden gate. Let’s take our time saying hello today.",
  "우체통 옆에 작은 꽃을 심었어. 네 편지가 머물 자리가 생겼네.":
      "I planted a tiny flower beside the mailbox. Now there’s a little place for your letters.",
  "처음 만난 날은 말이 짧아도 괜찮아. 나는 햇볕 드는 자리에 앉아 있을게.":
      "A few words are enough on our first day. I’ll be sitting in the sunshine.",
  "오늘은 방석을 한 뼘 가까이 옮겼어. 편한 만큼만 이야기해 줘.":
      "I moved my cushion a little closer today. Share only what feels comfortable.",
  "정원 길에 떨어진 잎을 주웠어. 편지 옆에 살짝 놓아둘게.":
      "I picked up a fallen leaf from the garden path. I’ll tuck it beside your letter.",
  "우체통에 작은 리본을 달았어. 길을 걷다가 편할 때 들러 줘.":
      "I tied a little ribbon on the mailbox. Stop by whenever it feels right.",
  "우리 정원에 벤치가 생겼어. 오늘은 나란히 앉아 바람을 구경하자.":
      "Our garden has a bench now. Let's sit side by side and feel the breeze.",
  "벤치 아래에 동그란 돌을 모았어. 모양이 달라도 함께 놓으니 예쁘네.":
      "I gathered round stones under the bench. Different shapes look lovely together.",
  "오늘은 정원 지도를 그려봤어. 아직 빈 곳은 천천히 채워 가자.":
      "I drew a map of our garden today. We can fill the empty spaces slowly.",
  "벤치 곁에 작은 지붕을 만들었어. 비가 오는 날에도 쉬어 갈 수 있게.":
      "I built a little roof by the bench, so there’s somewhere to rest on rainy days too.",
  "정원 지도에 쉬어 가는 곳을 하나 더 그렸어. 서둘러 도착할 필요는 없어.":
      "I added another resting spot to our garden map. There’s no hurry to get there.",
  "오늘은 우체통을 닦았어. 길게 쓰든 한 줄을 쓰든 편히 놓고 가도 돼.":
      "I cleaned the mailbox today. A long letter or a single line—leave whatever you like.",
  "정원 지도를 접어 우체통에 넣었어. 처음의 작은 방석도 여전히 그 자리에 있어.":
      "I folded the garden map into the mailbox. That first little cushion is still right where it was.",
  "새 씨앗을 심을 자리를 남겨뒀어. 오래된 정원에도 새로운 이야기는 자라니까.":
      "I left a place for new seeds. Even an old garden has room for new stories.",
  "오늘은 아무것도 만들지 않고 벤치에서 쉬었어. 우리 정원에는 그런 날도 있어.":
      "I didn’t make anything today. I just rested on the bench. Our garden has days like that too.",
  "직접 고른 {0}와 무작위로 만난 카드가 같네요. 반가운 우연이에요. 재미용 카드이며, 숨겨진 마음이나 미래를 알려주는 결과는 아니에요.":
      "The {0} cat you chose matches the random card. A lovely coincidence. This card is just for fun; it doesn’t reveal hidden feelings or predict the future.",
  "오늘 직접 고른 고양이는 {0}, 무작위 카드는 {1}예요. 재미용 카드이며, 서로 다르다고 마음에 모순이나 숨겨진 감정이 있다는 뜻은 아니에요.":
      "You chose {0} today, and the random card was {1}. The card is just for fun. A difference doesn’t mean you have conflicting or hidden feelings.",
  "이 고양이를 처음 골랐을 때 어떤 장면이 떠올랐나요? 원한다면 한 줄 남겨보세요.":
      "What came to mind when you first chose this cat? Leave a line if you’d like.",
  "{0}의 이야기에서 와닿는 부분이 있나요? 없다면 내가 고른 {1}의 이야기만 돌아봐도 좋아요.":
      "Does anything in {0}’s story resonate? If not, you can simply revisit the story of {1}, the cat you chose.",
  "카드에 나를 맞출 필요는 없어요. 내 마음에 대한 답은 내가 정해요. 그냥 넘겨도 괜찮아요.":
      "You don’t need to fit yourself to a card. You decide what your feelings mean. It’s okay to skip this.",
  "원한다면 주변의 색 하나를 가만히 바라보거나 편안하게 숨을 쉬어보세요. 오늘은 여기까지만 해도 충분해요.":
      "If you’d like, notice a color around you or take an easy breath. This can be enough for today.",
  "이번 달은 아직 기록이 충분하지 않아요. 편지를 몇 번 더 써보면\n흐름을 함께 살펴볼 수 있어요.":
      "There aren’t enough records to explore this month yet.\nA few more letters can help reveal what you’ve recorded over time.",
  "이번 달, 당신은 {0}와 함께했어요.": "This month, you spent time with {0}.",
  "이번 달, 당신은 꾸준히 {0}와 함께했어요.":
      "This month, {0} appeared throughout your records.",
  "이번 달, 당신의 감정은 초반엔 {0}에서\n후반엔 {1}로 흘러갔어요.":
      "In the first half of the month, {0} appeared most often;\nin the second half, it was {1}.",
  "오늘 편지에서 고른 마음과, 무작위로 뽑힌 카드가\n똑같이 {0}였어요. 반가운 우연이에요. 마음에 와닿는 부분만 돌아보세요.":
      "The feeling you chose in today’s letter and your random card\nwere both {0}. A lovely coincidence—reflect only on what resonates.",
  "오늘 편지에서는 {0}를 골랐지만,\n무작위로 뽑힌 카드는 {1}였어요. 서로 다른 결을 보여준 하루예요.":
      "You chose {0} in today’s letter,\nwhile your random card was {1}. Two different cards for one day.",
  "이번 달 무작위 카드뽑기에서 {0}가 {1}번\n나타났어요. 무작위 추첨 기록이며, 실제 감정이나 숨겨진 마음을 뜻하지 않아요.":
      "{0} appeared {1} times in this month’s random draws.\nThese are random results, not evidence of actual or hidden feelings.",
  "두 사람 모두 지금 '{name}'의 그림자를 품고 있어요.\n같은 결을 가진 두 마음이 나란히 서 있는 하루예요.":
      "You both chose the “{name}” mood cat.\nYou picked a similar feeling today.",
  "'{name}'이 두 사람에게 동시에 찾아왔어요.\n서로의 마음을 설명하지 않아도 알아볼 수 있는 순간일지도 몰라요.":
      "You both met “{name}”.\nMaybe something in this feeling is familiar to you both.",
  "당신의 그림자는 '{a}({ka})', 친구의 그림자는 '{b}({kb})'예요.\n서로 다른 결의 두 마음이 오늘 나란히 놓여 있어요.":
      "Your mood cat is “{a} ({ka})”, and your friend's is “{b} ({kb})”.\nTwo different feelings, side by side.",
  "'{a}'와 '{b}'가 오늘 만났어요.\n{ka}과 {kb}, 이 둘이 함께 있을 때 어떤 풍경이 될까요?":
      "“{a}” and “{b}” are together today.\nWhat comes to mind when you think of {ka} and {kb}?",
  "당신은 {ka}의 마음을, 친구는 {kb}의 마음을 지나고 있어요.\n각자의 속도로 흘러가는 두 결을 그대로 지켜봐 주세요.":
      "You chose {ka}, and your friend chose {kb}.\nThere's room for both feelings here.",
  "평균 온기 75~100": "Average warmth: 75–100",
  "평균 온기 50 이상 75 미만": "Average warmth: 50 to under 75",
  "평균 온기 25 이상 50 미만": "Average warmth: 25 to under 50",
  "평균 온기 0 이상 25 미만": "Average warmth: 0 to under 25",
  "기록된 온기 값이 늘었어요": "Recorded warmth increased",
  "기록된 온기 값이 낮아졌어요 · 보상 적립 여부를 함께 확인해요":
      "Recorded warmth decreased · Check whether a reward was earned",
  "기록된 온기 값이 비슷해요": "Recorded warmth stayed similar",
  "기록된 온기 값에 차이가 있어요 · 보상 후 다시 쌓일 수 있어요":
      "Recorded warmth varied · It can build again after a reward",
  "돌봄 온기는 출석·편지·돌봄 같은 활동으로 쌓는 값이에요. 감정이나 심리 상태를 측정한 점수가 아니에요. 구독자는 100에 도달하면 포인트를 받고 0부터 다시 쌓아요. 값이 낮아져도 마음이 나빠졌다는 뜻은 아니에요.":
      "Care warmth grows through activities such as check-ins, letters, and care. It does not measure emotions or mental health. Subscribers earn points at 100, then start building again from zero. A lower value doesn’t mean you’re feeling worse.",
  "이 기간에 저장된 온기의 평균은 {0}이에요. {1}":
      "Average warmth saved during this period: {0}. {1}",
  "내 마음을 돌아보고 싶다면 직접 고른 감정과 남긴 편지를 살펴보세요. 감정 통계에서 기록과 주간·월간 회고를 다시 볼 수 있어요.":
      "To reflect on your feelings, revisit the emotions you chose and the letters you wrote. Emotion statistics also include your records and weekly or monthly reflections.",
  "온기를 얼마나 모았는지로 마음이나 노력을 평가하지 않아요. 쉬었던 날에도 이전 돌봄이 사라지지 않아요.":
      "Warmth doesn’t measure your feelings or effort. Taking a day off doesn’t erase your earlier care.",
  "쉬고 싶을 때는 명상이나 호흡을 선택해도 좋아요. 온기 값에 따라 특정 활동이 필요하다고 판단하지 않아요.":
      "If you’d like a rest, you can choose meditation or breathing. Your warmth value doesn’t determine which activity you need.",
  "지금 걱정하는 일 중 오늘 내가 할 수 있는 작은 일은 무엇일까요?":
      "What’s one small thing I can do today about something that’s worrying me?",
  "오늘 어떤 방식의 연결이나 혼자만의 시간이 필요했나요?":
      "What kind of connection—or time alone—did I need today?",
  "오늘 내가 지키고 싶었던 경계나 소중한 것은 무엇이었나요?":
      "Was there a boundary I wanted to set, or something important I wanted to protect?",
  "오늘 고마웠던 장면을 하나 남겨볼까요?":
      "What's one thing I'm grateful for today?",
  "오늘의 기쁨을 어떤 장면으로 기억하고 싶나요?":
      "What happy moment from today would I like to remember?",
  "지금 나에게 필요한 것은 휴식일까요, 말할 상대일까요, 다른 무엇일까요?":
      "What do I need now: rest, someone to talk to, or something else?",
  "그때의 나에게 지금 건네고 싶은 말이 있나요?":
      "What would I like to say to my past self?",
  "기다리는 일에서 가장 기대되는 부분은 무엇인가요?":
      "What am I looking forward to most about what’s ahead?",
  "이 편안함 곁에 잠시 더 머물 수 있는 방법이 있을까요?":
      "What could help me enjoy this calm for a little longer?",
  "오늘 덜어낼 수 있는 일 하나가 있나요?": "Is there one thing I can take off my plate today?",
  "바라는 방향으로 아주 작게 해볼 수 있는 일이 있나요?":
      "What's one small step toward something I'm hoping for?",
  "답이 떠오르면 한 줄 적어보세요. 떠오르지 않으면 지금은 쉬어도 좋아요.":
      "If an answer comes, write a line. If it doesn’t, it’s okay to rest.",
  "이 질문은 내 경험을 돌아보는 초대예요. 맞지 않는 설명에 나를 맞출 필요는 없어요.":
      "This question is an invitation to reflect on your experience. You don’t have to fit an explanation that doesn’t feel right.",
  "원한다면 편안한 자세로 주변을 둘러보거나 자연스럽게 숨을 쉬어보세요. 불편하면 멈춰도 괜찮아요.":
      "If you’d like, get comfortable, look around, or breathe naturally. It’s okay to stop if it feels uncomfortable.",
  "정원 일기": "Garden journal",
  "아직 비교할 만큼의 기록이 쌓이지 않았어요.": "There aren’t enough records to compare yet.",
  "아직 분기 단위로 비교할 기록이 쌓이지 않았어요.":
      "There aren’t enough records for a quarterly comparison yet.",
  "아직 뚜렷한 요일·시간대 패턴을 찾기엔\n기록이 조금 더 필요해요.":
      "A few more records are needed\nto explore patterns by weekday and time of day.",
  "아직 다시 떠오른 감정이 없어요.\n무거운 마음이 있을 때 방울을 잠시 묻어두면,\n며칠 뒤 새싹으로 다시 만날 수 있어요.":
      "No buried feelings have returned yet.\nIf something feels heavy, you can leave a bubble in the earth\nand meet it again as a sprout in a few days.",
  "아직 데일리 카드뽑기 기록이 충분하지 않아요.\n무작위 카드 기록이에요. 실제 감정의 빈도를 뜻하지 않아요.":
      "There aren’t enough daily card draws yet.\nThese are random draws, not the frequency of your actual feelings.",
  "신청자 {0}": "Participant {0}",
  "신청 내역을 삭제하고 자리를 돌려드려요.":
      "Your registration will be removed and your place released.",
  "신청한 모임": "Registered event",
  "도움 여부는 남기지 않았어요": "No helpfulness feedback left",
  "기록을 확인해 주세요.": "Please check your records.",
  "먹구름이 잔뜩 낀 하늘 아래, 이 고양이는 눈물을 글썽이며 조용히 서 있어요. 뭔가 잃어버린 것 같은 먹먹함이 가슴 한켠에 자리잡아, 이유 모를 눈물이 자꾸만 차오른답니다. 슬픔을 참지 않아도 괜찮다는 걸, 이 고양이는 아직 잘 몰라요.":
      "Under a sky full of dark clouds, this cat stands quietly with tears in their eyes. There’s an ache that feels like something is missing, even when they can’t say why. They’re still learning that sadness doesn’t have to be held back.",
  "슬퍼도 괜찮아요. 눈물은 마음이 스스로를 돌보는 방법이에요.":
      "It’s okay to feel sad. Sometimes tears are a way of giving your feelings room.",
  "오늘은 억지로 웃지 않아도 돼요. 슬픔을 잠시 그대로 느껴보세요.":
      "You don’t have to force a smile today. Let sadness be here for a little while.",
  "흰 고양이가 맛있게 밥을 먹는 모습을 곁눈질하며, 이 고양이는 뾰로통한 표정을 감추지 못해요. \"왜 나는 저렇게 될 수 없을까\" 하는 생각에 마음이 조급해지고, 스스로가 작아지는 기분이 든답니다. 사실 그 안엔 자신도 인정받고 싶은 마음이 숨어 있어요.":
      "Watching a white cat enjoy dinner, this cat can’t quite hide their pout. “Why can’t that be me?” they wonder, feeling impatient and small. Underneath the jealousy is a wish to be noticed too.",
  "부러움은 내가 진짜 원하는 걸 알려주는 신호예요.":
      "Envy can offer a clue about something you truly want.",
  "부러웠던 것 하나를 적고, 그걸 갖기 위해 오늘 할 수 있는 작은 일을 찾아보세요.":
      "Write down one thing you envied, then look for a small step toward it today.",
  "뒤편에서 불길이 활활 타오르고, 이 고양이는 이빨을 드러내며 잔뜩 화가 나 있어요. 누군가 자신의 영역을 침범했거나 부당한 일을 당했을 때, 마음속에서 뜨거운 불이 확 타올랐답니다. 화를 억누르려 하지만 그 불씨는 몸 안에서 계속 들끓고 있어요.":
      "With flames rising behind them, this cat bares their teeth in anger. A crossed boundary or an unfair moment has sparked something fierce. They try to hold it down, but the embers keep glowing inside.",
  "화는 나쁜 감정이 아니에요. 나를 지키려는 강한 목소리예요.":
      "Anger isn’t a bad feeling. It may be speaking up for something you need to protect.",
  "몸을 크게 움직여 화를 밖으로 흘려보내 보세요. 스트레칭이나 걷기가 도움이 돼요.":
      "If it feels comfortable, try a stretch or a walk to give that energy somewhere to go.",
  "아기자기한 다육식물 화분들 사이에 당당히 앉은 이 고양이는 스스로가 꽤 마음에 드는 눈치예요. 작은 성취도 크게 기뻐할 줄 알고, 자신을 있는 그대로 사랑하는 법을 알고 있답니다. 가끔은 그 자신감이 우쭐함으로 보일까 조심스럽기도 해요.":
      "Sitting proudly among little pots of succulents, this cat seems quite happy with who they are. They celebrate small achievements and know a little about accepting themselves. Sometimes, though, they worry their confidence might look like showing off.",
  "당당함은 자랑이 아니라 자기 존중이에요. 오늘의 나를 인정해주세요.":
      "Confidence can be a form of self-respect. Give yourself credit for who you are today.",
  "오늘 잘한 일 한 가지를 소리 내어 스스로에게 칭찬해보세요.":
      "Say one thing you did well today out loud, just for yourself.",
  "초록 수풀 속에 몸을 숨긴 채, 이 고양이는 경계하는 눈빛으로 밖을 조심스레 내다봐요. 낯선 상황에 선뜻 나서기보다 먼저 안전을 확인하고 싶어 하는 신중한 성격이랍니다. 다만 너무 오래 숨어있다 보면 좋은 기회도 놓치게 될까 걱정이에요.":
      "Hidden in the green bushes, this cat carefully watches the world outside. They like to check that things feel safe before stepping into something unfamiliar. Sometimes they wonder what they might miss by staying hidden so long.",
  "조심스러운 마음은 나를 지키는 지혜예요. 천천히 나와도 괜찮아요.":
      "Being cautious can help you care for yourself. It’s okay to come out slowly.",
  "오늘은 아주 작은 용기 한 걸음만 내딛어보세요.": "Try just one small, brave step today.",
  "온몸을 바닥에 축 늘어뜨린 채, 이 고양이는 하루 종일 움직이지 않아요. 무엇을 해도 의미가 없게 느껴지고, 좋아하던 것들에도 흥미가 사라진 지 오래됐답니다. 게으르다고 스스로를 탓하지만, 사실은 마음이 쉬어야 할 때라는 신호예요.":
      "Stretched out on the floor, this cat can hardly bring themselves to move. Things feel less meaningful, and old favorites have lost their pull. They call themselves lazy, when what they may need is care and room to rest.",
  "쉬어도 괜찮아요. 지금은 채찍질이 아니라 다정한 쉼이 필요한 때예요.":
      "It’s okay to rest. A little kindness may serve you better than pushing harder.",
  "오늘은 딱 한 가지, 아주 작은 움직임만 해보세요. 그걸로 충분해요.":
      "If you can, try one tiny movement today. That can be enough.",
  "걱정 가득한 눈빛으로 앞발을 모아 입가에 댄 채, 이 고양이는 안절부절못하고 있어요. 아직 일어나지도 않은 일들을 미리 상상하며 불안해하고, 작은 소리에도 화들짝 놀란답니다. 사실 이 고양이는 그저 자신을 지키고 싶을 뿐이에요.":
      "Paws gathered near their mouth, this cat looks restless and worried. They imagine things that haven’t happened and startle at little sounds. Beneath it all is a wish to stay safe.",
  "불안은 위험을 미리 알려주려는 마음의 노력이에요. 지금은 안전해요.":
      "Anxiety may be trying to protect you. Take a moment to notice what you need right now.",
  "4-4-6 호흡을 세 번만 해보세요. 몸이 먼저 안정을 찾을 거예요.":
      "If comfortable, try three gentle breaths: in for four, pause for four, out for six. Return to your normal breathing if it feels uncomfortable.",
  "어두운 먹구름 아래, 이 고양이는 몸을 둥글게 웅크린 채 외로운 눈빛으로 정면을 바라봐요. 곁에 아무도 없다고 느껴질 때면 마음 한구석이 텅 빈 것처럼 시려온답니다. 다가가고 싶지만 상처받을까 두려워 조용히 거리를 두고 있어요.":
      "Curled up beneath dark clouds, this cat looks out with lonely eyes. When no one seems nearby, an empty ache settles inside. They want to reach out but keep their distance, afraid of getting hurt.",
  "혼자인 것 같아도, 당신을 걱정하는 마음이 여기 있어요.":
      "Even when you feel alone, you deserve care and connection.",
  "오늘은 소중한 사람에게 짧은 안부 인사를 건네보세요.":
      "Send a short hello to someone who matters to you, if you feel ready.",
  "머리 위에 물음표를 띄운 채, 얼굴이 반반씩 검고 흰 이 고양이는 어리둥절한 표정을 짓고 있어요. 여러 선택지 앞에서 무엇이 옳은지 갈피를 못 잡고, 마음이 이랬다저랬다 흔들린답니다. 답을 서두르기보다 잠시 멈춰 생각할 시간이 필요해요.":
      "With a question mark overhead, this black-and-white cat looks puzzled. There are so many choices, and none feels quite right. They keep changing their mind. Maybe they can take a break and decide later.",
  "지금 당장 답을 몰라도 괜찮아요. 혼란도 지나가는 과정이에요.":
      "You don’t have to know the answer right now. Uncertainty can be part of finding your way.",
  "고민을 종이에 적어보며 생각을 하나씩 정리해보세요.":
      "Put your thoughts on paper and take them one at a time.",
  "뒤를 돌아보며 눈물을 흘리는 이 고양이는 지나간 시간을 자꾸 떠올려요. 좋았던 순간들이 그리워 마음이 아릿해지고, 다시는 돌아갈 수 없다는 사실에 서글퍼진답니다. 그리움은 그만큼 소중했다는 증거이기도 해요.":
      "Looking back with tears in their eyes, this cat keeps returning to moments that are gone. Good memories bring both warmth and an ache, because they can’t go back. Missing something can show how much it mattered.",
  "그리움은 사랑했다는 증거예요. 그 마음을 부끄러워하지 않아도 돼요.":
      "It's natural to miss something that mattered to you. You don't have to hide it.",
  "그리운 순간을 짧게 글로 남겨 마음속에 고이 간직해보세요.":
      "Write a few words about a moment you miss, and keep it close.",
  "화난 표정으로 꼬리를 치켜세운 채, 이 고양이는 씩씩하게 앞만 보고 걸어가요. 한번 마음먹은 건 좀처럼 바꾸지 않고, 남의 말보다 자기 확신을 믿는 편이랍니다. 가끔은 그 고집이 스스로를 더 힘들게 만들기도 해요.":
      "Tail held high, this cat marches ahead with a determined frown. Once they’ve decided, they trust their own judgment more than anyone else’s. Sometimes, though, holding on so tightly makes the road harder.",
  "고집은 소신의 다른 이름이에요. 다만 가끔은 마음을 살짝 열어봐도 괜찮아요.":
      "Determination can help you stand by what matters. There can be room for another view too.",
  "오늘 한 가지 일에서만 다른 사람의 의견을 들어보세요.":
      "Choose one small thing today where you’re willing to hear someone else’s perspective.",
  "다리에 붕대를 감은 채, 꽃밭 한가운데서 이 고양이는 서럽게 울고 있어요. 마음이든 몸이든 어딘가 다쳐본 이는 알아요, 아무렇지 않은 척하는 게 얼마나 힘든지. 이 고양이에게는 낫기까지 기다려줄 시간과 다정한 보살핌이 필요해요.":
      "With a bandage around one leg, this cat cries in the middle of a flower garden. Anyone who has been hurt knows how tiring it can be to pretend everything is fine. This cat needs gentle care and time, without being rushed.",
  "상처는 약함이 아니라 애썼다는 흔적이에요. 천천히 나아가도 괜찮아요.":
      "Being hurt doesn’t make you weak. It’s okay to move forward slowly.",
  "오늘은 다친 마음에 밴드 하나 붙여주듯, 나를 다정하게 대해주세요.":
      "Be gentle with yourself today. What would help you feel a little more comfortable?",
  "두 발로 서서 무표정한 눈빛으로 정면을 응시하는 이 고양이는 좀처럼 감정을 드러내지 않아요. 무엇에도 크게 동요하지 않는 게 편할 때도 있지만, 가끔은 그 무심함 뒤로 진짜 감정을 숨기고 있는 건 아닌지 스스로도 헷갈린답니다.":
      "Standing still with an unreadable expression, this cat rarely shows what they feel. Staying unruffled can be comfortable, but sometimes they wonder what might be hidden underneath. Even they don’t always know.",
  "무심해 보여도 괜찮아요. 감정을 느끼는 속도는 저마다 다르니까요.":
      "You don't have to show or explain your feelings before you're ready.",
  "오늘 하루, 내 안에 어떤 감정이 있는지 딱 한 단어로 적어보세요.":
      "Try one word for a feeling you notice today. It’s okay if you’re not sure.",
  "굳게 닫힌 나무 문 앞에서, 이 고양이는 안절부절못하며 앞발로 문을 긁어요. 기다림이 길어질수록 마음이 조급해지고, 지금 당장 답을 알고 싶어 발톱을 세워 긁어본답니다. 하지만 어떤 문은 스스로 열릴 때까지 기다려야 해요.":
      "In front of a tightly shut wooden door, this cat scratches impatiently with one paw. The longer the wait, the more they want an answer now. But some doors can’t be hurried open.",
  "기다림도 성장의 한 과정이에요. 문은 때가 되면 열려요.":
      "Waiting can be part of the process. You don’t have to solve everything right now.",
  "오늘은 기다리는 동안 할 수 있는 작은 일 하나를 찾아 해보세요.":
      "Find one small thing you can do while you wait.",
  "거울 속에 비친 울고 있는 자신의 모습을 바라보며, 이 고양이는 화가 난 듯 소리를 지르고 있어요. 실수를 하면 스스로를 심하게 몰아세우고, \"왜 그것밖에 못했을까\" 하며 자신을 탓한답니다. 하지만 그 누구보다 자신에게 가장 엄격한 건 바로 이 고양이 자신이에요.":
      "Looking at their own tearful reflection, this cat cries out in frustration. A mistake quickly becomes “Why wasn’t I better?” No one seems harder on them than they are on themselves.",
  "실수해도 당신의 가치는 변하지 않아요. 스스로에게 조금 더 다정해도 돼요.":
      "A mistake doesn’t change your worth. You can be a little kinder to yourself.",
  "오늘 나를 탓하고 싶을 때, 친한 친구에게 하듯 부드럽게 말해주세요.":
      "When you notice self-blame today, try speaking to yourself as you would to a close friend.",
  "작은 회색 비구름을 머리 위에 인 채, 이 고양이는 바닥에 축 늘어져 멍하니 눈을 내리깔고 있어요. 특별히 슬픈 일이 있었던 것도 아닌데, 마음에 무거운 회색빛이 가만히 내려앉아 좀처럼 걷히지 않는답니다. 애써 기운을 내려 하지 않아도, 지금은 그냥 이 무게를 느껴도 괜찮아요.":
      "A little gray raincloud follows this cat as they lie quietly on the floor. Nothing especially sad has happened, yet a heaviness has settled and won’t quite lift. They don’t have to force their spirits up. For now, there can be room for how they feel.",
  "마음이 가라앉는 날도 있어요. 억지로 밝아지려 하지 않아도 당신은 괜찮아요.":
      "Some days feel low. You don’t have to act cheerful to deserve kindness.",
  "오늘은 아무것도 하지 않아도 되는 시간을 잠깐이라도 스스로에게 허락해보세요.":
      "Give yourself even a short stretch of time when nothing is expected of you.",
  "부서진 나무 다리 앞에서 뒤를 돌아보며, 이 고양이는 경계하는 표정을 짓고 있어요. 앞으로 나아가야 할지, 돌아가야 할지 쉽게 결정하지 못하고 망설이는 시간이 길어진답니다. 다리가 흔들려 보여도, 한 걸음씩 조심히 건너면 갈 수 있어요.":
      "At a broken wooden bridge, this cat looks back with hesitation. Go forward or turn around? The decision takes time. Before stepping ahead, they want to understand where it feels steady.",
  "망설임은 신중함의 다른 얼굴이에요. 준비가 되면 자연스레 나아가게 될 거예요.":
      "It's okay to pause before deciding. Take the time you need.",
  "오늘은 망설이던 일 중 가장 작은 부분만 살짝 시작해보세요.":
      "Start with the smallest part of something you’ve been hesitating about.",
  "보라색 꽃송이를 지붕 삼아, 이 고양이는 몸을 잔뜩 웅크린 채 눈을 반쯤 내려감고 있어요. 힘든 걸 애써 누르고 티 내지 않으려 버텨온 하루였답니다. 겉으론 괜찮아 보이려 했지만, 사실은 쉬고 싶다는 말을 삼켜온 지 오래됐어요.":
      "Under a purple flower, this cat curls up with half-closed eyes. They’ve spent the day hiding how hard things feel. They look okay from the outside, but they’ve been swallowing the words “I need a rest” for a long time.",
  "애써 버텨온 마음, 지금은 그만 내려놓아도 괜찮아요.":
      "If you've been pushing through, it's okay to take a break now.",
  "오늘은 억지로 힘내지 말고, 잠깐이라도 눈을 감고 쉬어보세요.":
      "Instead of making yourself push through, try closing your eyes for a little rest if that feels comfortable.",
  "팔짱을 낀 채 뾰로통한 표정으로 곁눈질하는 이 고양이는 단단히 삐쳐있어요. 서운한 마음을 솔직히 말하기보다 토라진 티를 팍팍 내며 알아주기를 바란답니다. 사실 그 안엔 이해받고 싶은 마음이 가득해요.":
      "Arms folded and eyes turned sideways, this cat is clearly sulking. Rather than saying what hurt, they hope someone will notice their pout. Underneath is a strong wish to be understood.",
  "삐친 마음 뒤엔 서운함이 있어요. 그 마음을 알아주는 것만으로도 괜찮아요.":
      "Sometimes it's hard to say that something hurt. You can start by noticing what you're feeling.",
  "서운했던 이유를 솔직하게 적어보고, 가능하다면 말로도 표현해보세요.":
      "Write honestly about what hurt. If it feels possible, try putting it into words for someone too.",
  "다른 고양이들이 어울려 노는 모습을 먼발치에서 바라보며, 이 고양이는 홀로 작은 섬에 쓸쓸히 앉아 있어요. 무리에 끼지 못하는 것 같은 기분에 마음이 움츠러들고, 자신만 뒤처진 것 같아 속상하답니다. 하지만 함께할 곳은 반드시 있을 거예요.":
      "Alone on a little island, this cat watches the others play in the distance. Feeling left out makes them shrink inward, as though everyone else has moved ahead. They’re still looking for a place where they can feel at home.",
  "지금 혼자처럼 느껴져도, 당신과 잘 맞는 자리가 분명 있어요.":
      "Feeling alone right now doesn’t mean you won’t find a place that fits.",
  "오늘은 나에게 편안한 사람 한 명에게 먼저 말을 걸어보세요.":
      "If you feel ready, say hello to one person you feel comfortable with.",
  "노란 꽃밭 속에 모여 앉아 서로 어깨를 맞대고, 이 고양이들은 환하게 웃으며 행복해하고 있어요. 함께 있는 것만으로도 마음이 따뜻해지고, 별것 아닌 순간에도 웃음이 끊이지 않는답니다. 이런 순간들이 삶을 든든하게 채워줘요.":
      "Sitting shoulder to shoulder in yellow flowers, these cats beam with happiness. Being together brings warmth, and even ordinary moments turn into laughter. Little moments like these can become something to lean on.",
  "지금 이 행복한 순간을 마음껏 누려도 괜찮아요.":
      "You’re allowed to enjoy this happy moment fully.",
  "오늘의 행복한 순간을 사진이나 글로 남겨보세요.":
      "Keep a photo or a few words about a happy moment today.",
  "분홍빛 꽃길 사이에서 서로 볼을 비비며, 이 고양이들은 사랑스럽게 안겨 있어요. 마음을 나눌 상대가 곁에 있다는 것만으로도 큰 위안이 되고, 다정함을 주고받는 법을 잘 알고 있답니다. 그 온기가 하루를 든든하게 채워줘요.":
      "Along a pink flower path, these cats nuzzle close. Having someone to share a little of their heart with feels comforting. They give and receive kindness, and that warmth stays with them through the day.",
  "다정함을 나눌 수 있는 오늘, 그 자체로 참 소중해요.":
      "A small act of kindness can mean a lot.",
  "가까운 사람에게 오늘 마음을 담아 작은 다정함을 표현해보세요.":
      "Offer someone close to you a small, heartfelt kindness today.",
  "커다란 연필을 손에 쥐고 진지한 표정으로 원을 그리는 이 고양이는 자신만의 영역을 만들어가는 중이에요. 하나에 깊이 몰입할 때 시간 가는 줄 모르고, 완성해가는 과정 자체에서 큰 즐거움을 느낀답니다. 몰입은 이 고양이에게 가장 큰 활력소예요.":
      "Holding a big pencil, this cat carefully draws a circle. When they become absorbed in something, time slips by. The joy is in making it, little by little. That feeling of focus brings them to life.",
  "몰입하는 순간, 당신은 가장 생생하게 살아있어요.":
      "It's a good feeling to lose yourself in something you enjoy.",
  "오늘 몰입하고 싶은 일 하나에 방해 없이 20분만 집중해보세요.":
      "If you can, set aside 20 quiet minutes for something you'd like to focus on.",
  "꽃밭 위를 신나게 뛰어다니며, 이 고양이는 기쁨에 가득 차 활기찬 표정을 짓고 있어요. 좋은 일이 생기면 온몸으로 그 기쁨을 표현하고, 에너지가 넘쳐 가만히 있질 못한답니다. 이 활기가 주변에도 좋은 영향을 준다는 걸 이 고양이는 아직 잘 몰라요.":
      "Bounding through the flowers, this cat can hardly contain their delight. Good news sends joy right through their whole body. They don’t yet realize how their enthusiasm can brighten the space around them.",
  "신나는 마음, 마음껏 표현해도 괜찮아요. 그 에너지가 참 좋아요.":
      "It’s okay to show your excitement. Let yourself enjoy that energy.",
  "오늘의 설렘을 몸을 움직이며 마음껏 발산해보세요.":
      "Move in a way that lets you express a little of today’s excitement.",
  "반짝이는 별빛 눈망울로, 이 고양이는 호기심 가득하게 무언가를 바라보고 있어요. 새로운 것을 발견하면 눈이 반짝이고, \"이건 뭘까?\" 하는 궁금증이 끊이지 않는답니다. 그 호기심이 이 고양이를 더 넓은 세상으로 이끌어줘요.":
      "With starlight in their eyes, this cat leans toward something new. Every discovery brings another “What’s that?” Their curiosity keeps opening little doors into a bigger world.",
  "궁금한 게 많다는 건 마음이 아직 활짝 열려있다는 뜻이에요.":
      "You don't have to know where curiosity will lead. It's okay to explore.",
  "오늘 궁금했던 것 하나를 직접 찾아보거나 시도해보세요.":
      "Look up or try one thing you felt curious about today.",
  "아름다운 푸른 꽃 아치 아래에서, 이 고양이는 나비들을 물끄러미 올려다보고 있어요. 시선은 또렷하지 않고 표정도 흐릿한 채로, 지금 이 마음이 슬픔인지 반가움인지 조차 스스로도 알기 어렵답니다. 굳이 이름 붙이려 애쓰지 않아도, 그저 이런 상태로 잠시 머물러도 괜찮아요.":
      "Beneath an arch of blue flowers, this cat gazes at butterflies. Their expression is hard to read, even to themselves. Is this sadness, a welcome feeling, or something else? They don’t have to name it yet. They can stay here a little while.",
  "지금 무슨 감정인지 몰라도 괜찮아요. 억누른 게 아니라, 아직 알아가는 중일 뿐이에요.":
      "It’s okay not to know what you’re feeling. You may still be getting to know it.",
  "오늘은 감정에 이름을 붙이려 하지 말고, 그냥 있는 그대로 가만히 느껴보세요.":
      "Let yourself notice what’s here today without trying to give it a name.",
  "은은하게 빛나는 초승달 앞에서 눈을 지긋이 감은 채, 이 고양이는 평온하게 휴식을 취하고 있어요. 소란스러운 마음이 잦아들고 고요함이 찾아온 이 순간, 무엇에도 흔들리지 않는 편안함을 느낀답니다. 평온함은 애써 만드는 게 아니라 그저 머무는 거예요.":
      "Eyes gently closed beneath a crescent moon, this cat rests in the quiet. The noise inside has settled for a moment, leaving a little ease. Calm isn’t something they need to force; for now, they can simply be here.",
  "지금 이 평온함을 충분히 느껴보세요. 참 잘 지내고 있어요.":
      "Take a moment to enjoy this little pocket of calm.",
  "오늘 하루 5분만 아무것도 하지 않고 고요히 앉아보세요.":
      "If you’d like, spend five quiet minutes sitting with nothing you need to do.",
  "무지개와 달빛 아래, 이 고양이들은 단란하게 함께 앉아 고요하고 만족스러운 시간을 보내고 있어요. 특별한 일이 없어도 지금 이 순간에 감사할 줄 알고, 있는 그대로의 하루에 편안함을 느낀답니다. 만족은 큰 것에서 오지 않는다는 걸 이 고양이는 잘 알아요.":
      "Beneath a rainbow and moonlight, these cats sit together in quiet contentment. Nothing remarkable needs to happen. There’s enough in this ordinary moment to appreciate. They know contentment can live in little things.",
  "지금 이대로도 충분해요. 오늘 하루에 감사한 마음을 가져보세요.":
      "There can be enough in this moment. Notice something you appreciate about today.",
  "몸을 살짝 웅크리고 시선을 피한 채, 이 고양이는 자꾸 작아지고 있어요. 무언가를 잘못해서가 아니라, 그냥 \"나 자신이 충분하지 않다\"는 낯선 감각이 마음 깊은 곳에서 스며든답니다. 잘못을 따지기보다, 존재 자체가 조용히 옅어지는 것 같은 기분이에요.":
      "Curling inward and avoiding eye contact, this cat feels smaller and smaller. It isn’t about something they did wrong; it’s the feeling of not being enough. For a moment, even their sense of belonging seems to fade.",
  "당신이 부족해서가 아니에요. 지금 그 마음은 지나가는 그림자일 뿐, 존재 자체는 흐려지지 않아요.":
      "Feeling like you're not good enough doesn't make it true. You belong here, just as you are.",
  "오늘은 잘못을 찾기보다, 그냥 \"나는 지금 여기 있어도 돼\"라고 조용히 말해보세요.":
      "Instead of searching for a fault today, try quietly saying, “I’m allowed to be here.”",
  "두 눈을 크게 뜨고 입을 꾹 다문 채, 이 고양이는 하고 싶은 말을 삼키며 가만히 서 있어요. 화를 내며 달려들기보다, 억울한 마음을 안으로 꾹꾹 눌러 참고 견디는 쪽이랍니다. 아무도 몰라줄까 봐, 숨이 막힐 듯 답답한 기분이 가슴에 고여 있어요.":
      "Eyes wide and mouth held shut, this cat swallows the words they want to say. Rather than lashing out, they press their sense of unfairness deep inside. It feels tight in their chest, and they worry no one will understand.",
  "말하지 못한 그 마음, 무시당한 게 아니에요. 지금이라도 당신의 목소리를 들어줄 사람이 필요해요.":
      "Words you haven’t been able to say still matter. You deserve a chance to be heard.",
  "삼켰던 말을 종이에 그대로 옮겨 적어보세요. 누구에게도 보여주지 않아도 괜찮아요.":
      "Write down the words you’ve been holding back. You don’t have to show them to anyone.",
  "먼 곳을 멍하니 바라보며, 이 고양이는 몸에 힘을 하나도 주지 않고 늘어져 있어요. 기운이 없어서가 아니라, 무엇을 해도 다 무슨 의미인지 흐릿해져 버린 것 같은 기분이랍니다. 눈앞의 것들이 초점 없이 뭉개져 보이고, \"왜\"라는 질문조차 희미해진 순간이에요.":
      "Gazing into the distance, this cat lies without much energy. It’s less about tiredness than a sense that things have lost their meaning. Everything feels out of focus, and even the question “Why?” seems far away.",
  "의미가 안 보인다고 당신이 잘못된 게 아니에요. 가끔은 의미를 찾지 않고 그냥 흘러가도 괜찮아요.":
      "You don't need to find meaning in everything right now. It's okay to take things a moment at a time.",
  "오늘은 답을 찾으려 하지 말고, 눈에 보이는 것 하나를 가만히 오래 바라보세요.":
      "Instead of looking for an answer today, spend a little time noticing one thing in front of you.",
  "두 앞발을 가만히 모으고 눈을 살짝 감은 채, 이 고양이는 조용히 미소 짓고 있어요. 화려하게 표현하지 않아도, 오늘 있었던 작은 것들에 마음이 따뜻해진답니다. 소란스럽지 않은 이 잔잔한 기쁨이, 하루를 은은하게 채워줘요.":
      "Paws gently together and eyes half-closed, this cat wears a quiet smile. Small moments from the day have warmed their heart. Their happiness doesn’t need a grand display; it quietly fills the spaces in between.",
  "감사는 크게 소리치지 않아도 충분해요. 지금 그 조용한 따뜻함을 그대로 느껴보세요.":
      "Gratitude doesn’t have to be loud. Let yourself feel this quiet warmth.",
  "오늘 고마웠던 아주 작은 것 하나를 마음속으로 가만히 되새겨보세요.":
      "Bring to mind one very small thing you appreciated today.",
  "한쪽 입꼬리를 슬쩍 올리며, 이 고양이는 흘러가는 풍경을 시큰둥하게 바라보고 있어요. 무심해서가 아니라, \"어차피 다 그런 거지\" 하는 씁쓸한 체념이 마음 한켠에 자리 잡은 거예요. 무엇에도 크게 기대하지 않게 된 지금이, 스스로도 조금은 낯설게 느껴진답니다.":
      "With one corner of their mouth raised, this cat watches the world go by. It’s not quite indifference; more a weary “That’s just how things are.” Expecting so little feels unfamiliar, even to them.",
  "냉소는 상처받지 않으려는 나름의 방식이었을 거예요. 그 마음도 이해받을 자격이 있어요.":
      "Cynicism may have been one way to avoid getting hurt. That part of you deserves understanding too.",
  "오늘은 시큰둥해지기 전에, 그 뒤에 숨은 진짜 기대를 한 번 들여다보세요.":
      "Before brushing something off today, notice whether there’s a hope underneath.",
  "몸을 돌린 채 어깨너머로 살짝 돌아보며, 이 고양이는 눈가에 눈물을 그렁그렁 매달고 있어요. 크게 소리 내어 울 만큼 슬픈 건 아니지만, \"나를 잊었나봐\" 하는 서운함이 조용히 마음에 고인답니다. 말하면 유치해 보일까 봐, 그냥 삼키고 돌아서는 쪽을 택하는 거예요.":
      "Turning away but glancing back over one shoulder, this cat has tears gathering in their eyes. It’s not quite a sob, more a quiet “Maybe they forgot about me.” Afraid of seeming childish, they swallow the feeling and walk away.",
  "서운함을 느끼는 건 그만큼 마음을 썼다는 뜻이에요. 그 마음, 작지 않아요.":
      "Feeling hurt can show that you cared. That feeling isn’t too small to matter.",
  "오늘은 서운했던 순간을 한 문장으로 적어, 스스로에게만 솔직히 인정해주세요.":
      "Write one honest sentence about a moment that hurt, just for yourself.",
  "몸을 작게 웅크리고 고개를 푹 숙인 채, 이 고양이는 자기 자신이 한없이 작아 보인다고 느껴요. 누군가와 다투거나 한 번 부러웠던 순간이 아니라, \"나는 원래부터 부족한 존재인가봐\" 하는 오래된 무게가 등 뒤에 크게 그림자처럼 걸려 있는 듯한 기분이에요.":
      "Curled small with their head lowered, this cat feels as though they’ve never quite been enough. It isn’t one argument or a passing comparison. It’s an old weight that seems to cast a large shadow behind them.",
  "누군가와 비교해서 매겨진 값이 당신의 전부는 아니에요. 당신은 이미 고유해요.":
      "A comparison can’t capture all of who you are. There’s no one else quite like you.",
  "오늘은 남과 비교하지 않고, 오직 나만이 가진 장점 하나를 떠올려보세요.":
      "Think of one strength that belongs to you, without comparing it with anyone else’s.",
  "몸을 바짝 낮추고 얼어붙은 채, 이 고양이는 눈을 커다랗게 뜨고 꼼짝도 못 하고 있어요. 그저 조금 불안한 정도가 아니라, 지금 당장 무언가 위협적인 일이 닥칠 것 같은 강렬한 공포가 온몸을 덮친 거예요. 숨조차 조심스럽게 쉬어야 할 것 같은, 그런 긴박한 순간이랍니다.":
      "Low to the ground and frozen in place, this cat stares with wide eyes. This is more than a little worry; it feels as though something threatening is about to happen. Even taking a breath seems to require care.",
  "두려움이 이렇게 크다는 건, 지금 당신에게 안전함이 꼭 필요하다는 신호예요.":
      "When fear feels this strong, your need for safety matters.",
  "오늘은 발이 닿은 자리를 꾹꾹 눌러보며, 지금 여기가 안전하다는 걸 몸으로 확인해보세요.":
      "If you are somewhere safe, gently press your feet against the floor and notice the support beneath them.",
  "앞발을 가슴에 얹고 고개를 숙인 채, 이 고양이는 걱정스러운 눈빛으로 위를 슬쩍 올려다보고 있어요. 자신을 몰아세우기보다, \"그때 그 말은 하지 말았어야 했는데\" 하며 누군가에게 미안한 마음이 자꾸 떠오른답니다. 잘못을 바로잡고 다시 다가가고 싶은, 관계를 향한 마음이에요.":
      "One paw on their chest, this cat looks up with worried eyes. Rather than blaming their whole self, they keep thinking, “I wish I hadn’t said that.” They want to make things right and find a way back toward someone they care about.",
  "미안한 마음이 든다는 건, 그 관계를 소중히 여긴다는 뜻이에요. 진심을 전할 기회는 아직 있어요.":
      "Feeling sorry can reflect how much a relationship matters. There may still be room for an honest conversation.",
  "오늘은 미안했던 마음을 짧게라도 그 사람에게 전해보는 걸 생각해보세요.":
      "Consider whether you’d like to share a few sincere words of apology today.",
  "나에게 조금 다정해지기": "A little kinder to myself",
  "고양이가 작은 방석을 창가에 놓았어요. 아무것도 해내지 않아도 앉을 수 있는 자리래요.":
      "Your cat placed a small cushion by the window. It’s a place you can sit without having to earn it.",
  "오늘 나에게 조금 덜 엄격해져도 되는 일은 무엇인가요?":
      "Where could I be a little less hard on myself today?",
  "원한다면 쉬어 갈 자리에서 잠깐 앉아보세요.":
      "If you’d like, sit for a moment somewhere you can rest.",
  "정원에는 빨리 자라는 풀도, 아직 흙 아래 있는 씨앗도 있어요. 고양이는 두 곳에 똑같이 물을 주었어요.":
      "Some grass in the garden grows quickly; some seeds are still under the soil. Your cat watered both with the same care.",
  "남과 비교하지 않고 인정하고 싶은 내 속도가 있나요?":
      "Where would I like to go at my own pace, without comparing myself to others?",
  "작아도 내가 해낸 일 하나를 적어보세요.": "Write down one thing you did, however small.",
  "고양이가 울퉁불퉁한 돌을 벤치 옆에 놓았어요. 반듯하지 않아도 마음에 드는 모양이래요.":
      "Your cat set a lumpy stone beside the bench. It isn't perfectly smooth, but they like it just the way it is.",
  "고치려 애쓰기 전에 받아들여도 되는 내 모습이 있나요?":
      "Is there a part of myself I could accept before trying to change it?",
  "오늘 나에게 해주고 싶은 말을 한 줄 남겨보세요.":
      "Leave yourself one line you’d like to hear today.",
  "한 달의 편지를 상자에 모았어요. 고양이는 가장 긴 편지 대신 다시 읽고 싶은 편지부터 골랐어요.":
      "A month of letters went into a box. Your cat didn’t choose the longest one first, but the one they wanted to read again.",
  "이번 여정에서 다시 읽고 싶은 내 문장은 무엇인가요?":
      "Which of my own words would I like to read again?",
  "기록에서 편지 한 통을 다시 읽어보세요.":
      "Choose one letter from your journal to read again.",
  "내 마음의 문 돌보기": "Caring for my boundaries",
  "정원 문에 작은 손잡이가 생겼어요. 열어 둘 때와 닫아 둘 때를 정하는 건 정원의 주인이래요.":
      "There's a new handle on the garden gate. You can decide when to open it and when you'd rather have some time to yourself.",
  "지금 나에게 필요한 거리는 어느 정도인가요?": "How much space do I need right now?",
  "오늘 선택할 수 있는 작은 거절이나 요청을 떠올려보세요.":
      "Think of one small request you'd like to make, or something you'd like to say no to.",
  "고양이는 방문객을 위해 의자를 놓고 자기 방석도 남겨뒀어요. 둘 다 놓을 자리가 있었어요.":
      "Your cat put out a chair for a visitor and kept a cushion for themselves. There was room for both.",
  "다른 사람을 배려하면서 놓치고 있던 내 필요가 있나요?":
      "Have I overlooked something I need while caring for someone else?",
  "원하는 것을 짧은 문장으로 적어보세요.": "Write what you want in one short sentence.",
  "바람이 강한 날에는 정원 문을 조금 닫았어요. 고양이는 바람이 잦아든 뒤 다시 열기로 했어요.":
      "When the wind grew strong, your cat partly closed the gate. They could open it again once the wind settled.",
  "바로 답하지 않고 시간을 가져도 되는 일이 있나요?":
      "Is there something I can take time with instead of answering right away?",
  "가능하다면 답하기 전에 잠깐 쉬어보세요.":
      "If you can, pause for a little rest before responding.",
  "문 옆에 작은 꽃이 피었어요. 고양이는 닫았던 날도 열었던 날도 정원을 돌본 날이라고 했어요.":
      "A small flower bloomed by the gate. Your cat said that opening it and closing it could both be ways of caring for the garden.",
  "이번 여정에서 나를 존중했던 순간을 하나 고른다면요?":
      "When did I make a choice that felt right for me?",
  "내 선택을 평가하지 않고 한 줄 기록해보세요.":
      "Write one line about a choice you made, without judging it.",
  "작은 기쁨 발견하기": "Finding little joys",
  "고양이가 창틀의 햇빛을 따라 움직였어요. 멀리 가지 않아도 밝은 자리가 있었어요.":
      "Your cat followed the sunlight along the windowsill. They didn’t have to go far to find a brighter spot.",
  "오늘 잠깐 눈길이 머문 장면은 무엇인가요?": "What caught my eye for a moment today?",
  "주변에서 마음에 드는 색 하나를 찾아보세요.": "Find a color nearby that you enjoy.",
  "정원 한쪽에서 이름 모를 풀을 발견했어요. 고양이는 이름을 알아내기 전에 모양부터 구경했어요.":
      "Your cat discovered an unfamiliar plant in a corner of the garden. Before learning its name, they simply enjoyed its shape.",
  "잘하지 않아도 궁금한 일이 있나요?":
      "Is there something I’m curious about, even if I’m not good at it?",
  "가능하면 궁금했던 것을 잠깐 살펴보세요.":
      "If you can, spend a little time exploring something that interests you.",
  "고양이가 아끼던 리본을 우체통에 달았어요. 작은 장식 하나로 익숙한 길이 달라 보였어요.":
      "Your cat tied a favorite ribbon to the mailbox. One tiny decoration made the familiar path feel a little different.",
  "내 하루에 더하고 싶은 작은 즐거움이 있나요?":
      "What small pleasure would I like to add to my day?",
  "부담 없이 할 수 있는 즐거운 일 하나를 골라보세요.":
      "Choose something enjoyable that feels easy to fit into today.",
  "고양이는 모아둔 잎과 돌을 늘어놓았어요. 대단한 것은 없어도 정원에서 보낸 시간이 담겨 있었어요.":
      "Your cat laid out the leaves and stones they had collected. Nothing grand, just little traces of time spent in the garden.",
  "다음 달에도 함께 가져가고 싶은 작은 기쁨은 무엇인가요?":
      "What little joy would I like to bring with me into next month?",
  "기억하고 싶은 장면을 편지에 남겨보세요.": "Keep a moment you’d like to remember in a letter.",
  "오늘 감사했던 순간 세 가지를 떠올려보세요.":
      "Bring to mind three moments you appreciated today.",
  "앱의 계정 연결을 시작하지 못했어요. 앱을 다시 실행해 주세요. 계속되면 오류 코드 AUTH-01을 알려 주세요.":
      "We couldn’t start account sign-in. Restart the app. If this continues, contact us with code AUTH-01.",
  "이 앱에 로그인 서버 주소가 설정되지 않았어요. 수정된 앱으로 업데이트해 주세요. (AUTH-02)":
      "This app is missing its sign-in server configuration. Please update to the corrected version. (AUTH-02)",
  "선택한 로그인 서비스의 서버 설정이 아직 완료되지 않았어요. 오류 코드 AUTH-03을 알려 주세요.":
      "The selected sign-in provider isn’t fully configured on the server. Contact us with code AUTH-03.",
  "이 로그인 방식은 아직 연결 준비 중이에요. 다른 방법을 선택해 주세요.":
      "This sign-in method isn’t ready yet. Please choose another method.",
  "간편로그인은 현재 안드로이드 앱에서 이용할 수 있어요.":
      "Social sign-in is currently available in the Android app.",
  "현재 계정을 먼저 로그아웃한 뒤 다른 계정으로 로그인해 주세요.":
      "Sign out of your current account before signing in to another one.",
  "로그인 계정이 바뀌었어요. 현재 계정을 확인해 주세요.":
      "Your signed-in account has changed. Please check the current account.",
  "로그인 시간이 지났어요. 다시 시작해 주세요.":
      "Your sign-in session has expired. Please start again.",
  "로그인 확인에 실패했어요. 앱에서 다시 시작해 주세요.":
      "We couldn’t verify sign-in. Please start again from the app.",
  "설치된 앱의 인증을 확인하지 못해 로그인을 계속할 수 없어요. 오류 코드 AUTH-04를 알려 주세요.":
      "We couldn’t verify this app installation, so sign-in can’t continue. Contact us with code AUTH-04.",
  "앱 인증 확인이 지연되고 있어요. 연결을 확인하고 다시 시도해 주세요. (AUTH-05)":
      "App verification is taking longer than expected. Check your connection and try again. (AUTH-05)",
  "로그인 서버에 연결하지 못했어요. 인터넷 연결을 확인하고 다시 시도해 주세요. (AUTH-06)":
      "We couldn’t reach the sign-in server. Check your internet connection and try again. (AUTH-06)",
  "로그인 서버를 찾지 못했어요. 오류 코드 AUTH-07을 알려 주세요.":
      "We couldn’t find the sign-in server. Contact us with code AUTH-07.",
  "로그인 서버가 앱의 요청을 받아들이지 못했어요. 오류 코드 AUTH-08을 알려 주세요.":
      "The sign-in server couldn’t accept this request. Contact us with code AUTH-08.",
  "로그인 서버의 응답을 확인하지 못했어요. 오류 코드 AUTH-09를 알려 주세요.":
      "We couldn’t validate the sign-in server response. Contact us with code AUTH-09.",
  "로그인 서버의 응답이 늦어지고 있어요. 잠시 후 다시 시도해 주세요. (AUTH-10)":
      "The sign-in server is taking longer than expected. Please try again shortly. (AUTH-10)",
  "선택한 서비스에서 로그인 인증을 완료하지 못했어요. 다시 시도해 주세요. (AUTH-11)":
      "The selected provider couldn’t complete sign-in. Please try again. (AUTH-11)",
  "로그인 창을 열거나 앱으로 돌아오는 중 오류가 발생했어요. 오류 코드 AUTH-12를 알려 주세요.":
      "Something went wrong opening sign-in or returning to the app. Contact us with code AUTH-12.",
  "계정 인증을 확인하지 못했어요. 로그아웃 후 다시 로그인해 주세요.":
      "We couldn’t verify your account. Sign out and sign in again.",
  "선택한 로그인 계정의 인증이 만료되었어요. 간편로그인을 다시 시작해 주세요.":
      "Your sign-in credentials have expired. Please start social sign-in again.",
  "계정 처리가 진행 중이에요. 잠시 후 로그인을 다시 시작해 주세요.":
      "An account operation is in progress. Please try signing in again shortly.",
  "이용이 중지된 계정이에요. 문의해 주세요.":
      "This account has been disabled. Please contact support.",
  "요청이 많아요. 잠시 후 로그인을 다시 시작해 주세요.":
      "Too many requests. Wait a little before signing in again.",
  "로그인을 처음부터 다시 시작해 주세요.": "Please restart sign-in from the beginning.",
  "삭제된 계정이에요. 계정 복구가 필요하면 문의해 주세요.":
      "This account has been deleted. Contact support if you need help with recovery.",
  "로그인이 진행 중이에요.": "Sign-in is in progress.",
  "로그인을 완료하지 못했어요. 연결을 확인하고 다시 시도해 주세요.":
      "We couldn’t complete sign-in. Check your connection and try again.",
  "로그인 전": "Not signed in",
  "이메일 주소를 확인해 주세요.": "Please check your email address.",
  "이메일과 비밀번호를 확인해 주세요.": "Please check your email and password.",
  "이미 이용하던 계정이 있어요. 기존 로그인 방법으로 접속해 주세요. 계정과 구매 내역은 자동으로 합치지 않아요.":
      "An account already exists. Use your original sign-in method. Accounts and purchase histories aren’t merged automatically.",
  "이 Google 계정은 다른 마음냥 계정에 연결되어 있어요. 기존 계정으로 로그인해 주세요.":
      "This Google account is linked to another Mindnyang account. Please sign in to that account.",
  "이 계정에는 이미 Google 로그인이 연결되어 있어요.":
      "Google sign-in is already linked to this account.",
  "로그인 서버 연결을 확인하지 못했어요. 최신 앱인지 확인한 뒤 다시 시도해 주세요.":
      "We couldn’t verify the sign-in server connection. Make sure you have the latest app, then try again.",
  "안전한 처리를 위해 로그아웃한 뒤 다시 로그인해 주세요.":
      "For a secure retry, sign out and sign in again.",
  "잠시 쉬었다가 다시 시도해 주세요.": "Please wait a little, then try again.",
  "이 로그인 방식은 아직 연결 준비 중이에요.": "This sign-in method isn’t ready yet.",
  "인터넷 연결을 확인하고 다시 시도해 주세요.": "Check your internet connection and try again.",
  "로그인을 완료하지 못했어요. 다시 시도해 주세요.":
      "We couldn’t complete sign-in. Please try again.",
  "응답이 늦어지고 있어요. 연결을 확인하고 다시 시도해 주세요.":
      "The response is taking longer than expected. Check your connection and try again.",
  "완료하지 못했어요. 연결을 확인하고 다시 시도해 주세요.":
      "We couldn’t finish. Check your connection and try again.",
  "박은정 (마음냥 정원)": "박은정 (Mindnyang Garden)",
  "운영·문의: {0}\n일반 문의·개인정보 문의·계정 삭제 요청: {1}":
